_COVERAGE_REGISTRY: dict[str, dict] = {}
# The rendered documents a hook may legitimately live in.
_DOC_KEYS = ("page", "eph", "empty_page", "degraded_page", "hub", "hub_empty",
             "hub_all")
# Every document is the one app document now — a repo page in each state it
# renders in, and the hub home over three rosters — so the checks that read
# "every state the page renders in" read all of them.
_APP_DOC_KEYS = _DOC_KEYS


def _covers(name: str, *, kind: str, hook: str | None = None,
            check: str | None = None, breaks=()):
    """Register `fn` as THE check for behaviour `name`.

    kind="rendered" names the data-kw-* hook the check binds to; kind="behaviour"
    names the check that exercises it (its own callable). `breaks` are the
    negative controls: each takes the true context and returns the artifact
    overrides that deliberately break this behaviour."""
    def deco(fn):
        _COVERAGE_REGISTRY[name] = {"kind": kind, "hook": hook,
                                    "check": check or fn.__name__,
                                    "fn": fn, "breaks": list(breaks)}
        return fn
    return deco


# --- structural readers: attributes, element relationships, resolved tokens ---

def _tags_with(doc: str, hook: str) -> list[str]:
    """Every start tag in `doc` carrying `hook` as an attribute name, static
    (`data-kw-x`) or bound (`:data-kw-x`). Never matches a longer hook."""
    pat = re.compile(r"(?<![\w-]):?" + re.escape(hook) + r"(?![\w-])")
    return [m.group(0) for m in re.finditer(r"<[a-zA-Z][^<>]*>", doc)
            if pat.search(m.group(0))]


def _tag_name(tag: str) -> str:
    m = re.match(r"<([a-zA-Z][\w-]*)", tag)
    return m.group(1) if m else ""


def _tag_after(doc: str, tag: str) -> str:
    """The next start tag following `tag` — the child a wrapper element opens
    with. Kept here rather than inline in a check so the checks stay free of
    markup-shaped string literals."""
    i = doc.index(tag) + len(tag)
    m = re.search(r"<[a-zA-Z][^<>]*>", doc[i:])
    return m.group(0) if m else ""


def _subtree(doc: str, start_tag: str) -> str:
    """The element `start_tag` opens, from its own start tag through its matching
    end tag. Depth-counted over same-named tags, so a nested element of the same
    name cannot close it early. Kept here rather than inline in a check for the
    same reason as _tag_after: the checks navigate structure, they never carry
    markup-shaped literals. An unclosed element yields the rest of the document,
    which is the conservative answer for an "is X inside this?" question."""
    name = _tag_name(start_tag)
    start = doc.index(start_tag)
    at, depth = start + len(start_tag), 1
    edge = re.compile(r"<(/?)" + re.escape(name) + r"(?![\w-])[^<>]*>")
    while depth:
        m = edge.search(doc, at)
        if not m:
            return doc[start:]
        depth += -1 if m.group(1) else 1
        at = m.end()
    return doc[start:at]


def _start_tags(doc: str) -> list[str]:
    """Every start tag in `doc`, in source order. The checks ask questions about
    elements — what kind, what rule — and this is how they get the elements
    without carrying a markup fragment to compare against."""
    return [m.group(0) for m in re.finditer(r"<[a-zA-Z][^<>]*>", doc)]


def _tags_named(doc: str, name: str) -> list[str]:
    """Every start tag in `doc` whose element name is `name`. Same reason as
    _tag_after: the checks navigate structure, they do not match markup."""
    return [m.group(0) for m in re.finditer(r"<[a-zA-Z][^<>]*>", doc)
            if _tag_name(m.group(0)) == name]


# Elements that never open a nesting level: the HTML void set, plus Vue's own
# `template`, which renders no element at all — a `v-for` on one is a loop, not
# a box, and counting it as a level would make the page look deeper than it
# paints.
_NON_NESTING = {"area", "base", "br", "col", "embed", "hr", "img", "input",
                "link", "meta", "param", "source", "track", "wbr", "template"}


def _containers_between(doc: str, outer: str, inner: str) -> list[str]:
    """The start tags still OPEN when `inner` is reached, counted inwards from
    `outer` and not including it — the boxes an element actually sits inside.

    This is how "how deeply is a card nested" is asked without counting tags
    that are not levels: a void or self-closing element opens nothing, a Vue
    `template` paints nothing, and an end tag closes the nearest matching start
    rather than whatever happens to be on top."""
    start, stop = doc.index(outer) + len(outer), doc.index(inner)
    stack: list[str] = []
    for m in re.finditer(r"<(/?)([a-zA-Z][\w-]*)([^<>]*)>", doc[start:stop]):
        closing, name, rest = m.group(1), m.group(2).lower(), m.group(3)
        if closing:
            for i in range(len(stack) - 1, -1, -1):
                if _tag_name(stack[i]).lower() == name:
                    del stack[i:]
                    break
        elif name not in _NON_NESTING and not rest.rstrip().endswith("/"):
            stack.append(m.group(0))
    return stack


def _child_tags(doc: str, outer: str) -> list[str]:
    """The start tags of `outer`'s DIRECT children, in source order — the boxes
    one level in, counted the way _containers_between counts: a void element
    opens nothing, a Vue `template` paints nothing (so what it wraps are still
    `outer`'s own children), and an end tag closes the nearest matching start."""
    block = _subtree(doc, outer)
    stack: list[str] = []
    out: list[str] = []
    for m in re.finditer(r"<(/?)([a-zA-Z][\w-]*)([^<>]*)>", block[len(outer):]):
        closing, name, rest = m.group(1), m.group(2).lower(), m.group(3)
        if closing:
            for i in range(len(stack) - 1, -1, -1):
                if _tag_name(stack[i]).lower() == name:
                    del stack[i:]
                    break
        else:
            if not stack and name != "template":
                out.append(m.group(0))
            if name not in _NON_NESTING and not rest.rstrip().endswith("/"):
                stack.append(m.group(0))
    return out


_CONDITIONAL_ATTRS = ("v-if", "v-else-if", "v-else", "v-show")


def _trailing_children(doc: str, outer: str) -> list[str]:
    """Every child of `outer` that can render LAST, innermost-last first: the
    final child in source order, and — for as long as that child is conditional
    (a v-if, v-else, v-show) and so may be absent — the one before it too,
    stopping at the first child that is always there. A footer guarded by a
    v-if is the last child when it renders and its elder sibling is the last
    child when it does not, and a question about "the last child" has to be
    asked of both."""
    out: list[str] = []
    for child in reversed(_child_tags(doc, outer)):
        out.append(child)
        if not any(a in _attrs(child) for a in _CONDITIONAL_ATTRS):
            break
    return out


def _rules_for_tag(css: str, tag: str) -> list[dict[str, str]]:
    """Every declaration block the stylesheet gives `tag`'s classes, in sheet
    order — what the element actually resolves to, rather than one rule of it."""
    return [d for cls in _attrs(tag).get("class", "").split()
            for d in _decls_for(css, "." + cls)]


# a box shorthand's four steps, in the order CSS states them
_BOX_STEPS = ("top", "right", "bottom", "left")

# what a length reads as when it is stated in something this cannot add up
_UNREADABLE = "?"


def _box_shorthand(value: str) -> list[str]:
    """A 1-to-4-value box shorthand expanded to its four steps. One value fills
    all four, two split vertical/horizontal, three state top, HORIZONTAL, bottom
    — which is the trap this exists for: a three-value padding's third step is
    its bottom, and reading it as the left one lets a wide frame declare itself
    narrow. Anything else yields no steps, and a caller reads that as unusable
    rather than as zero."""
    parts = value.split()
    if len(parts) == 1:
        return parts * 4
    if len(parts) == 2:
        return [parts[0], parts[1], parts[0], parts[1]]
    if len(parts) == 3:
        return [parts[0], parts[1], parts[2], parts[1]]
    return parts if len(parts) == 4 else []


def _box_side(decls: list[dict[str, str]], prop: str, side: str) -> str:
    """What `prop` resolves to on one `side` across `decls` in cascade order —
    longhand and shorthand alike, later declarations winning. An undeclared
    property yields the empty string, which the caller reads as zero."""
    value, want = "", prop + "-" + side
    for block in decls:
        for name, raw in block.items():
            if name == prop:
                steps = _box_shorthand(_norm(raw))
                value = steps[_BOX_STEPS.index(side)] if steps else _UNREADABLE
            elif name == want:
                value = _norm(raw)
    return value


_PX_RE = re.compile(r"(\d+)px")
# a CSS zero, in the unitless spelling and in every unit — zero is zero in all
# of them, so it costs nothing whichever way it was written
_ZERO_RE = re.compile(r"0[a-z%]*")


def _radius_corners(value: str) -> tuple[int, int, int, int] | None:
    """A border-radius declaration as its four corners in whole pixels —
    top-left, top-right, bottom-right, bottom-left, the order CSS states them —
    with a one-to-four value shorthand expanded. The shorthand fills in exactly
    as a box shorthand does (one value for all four, two for the diagonals,
    three for top-left / the other diagonal / bottom-right), so the same
    expander reads it. None for a radius stated in anything that is not a bare
    pixel length in every corner — a percentage, a var(), an elliptical pair
    with a slash — and for no radius at all, so a caller cannot mistake an
    unreadable corner for a square one.

    This is the reader that sees a bottom-only pair. A single bare length was
    the only shape the shape check used to read, so a container whose corners
    were written as a shorthand was skipped outright and went unguarded."""
    value = _norm(value)
    if not value or "/" in value:
        return None
    corners = [_px_length(part) for part in _box_shorthand(value)]
    if len(corners) != 4 or any(c is None for c in corners):
        return None
    return (corners[0], corners[1], corners[2], corners[3])


def _px_length(value: str) -> int | None:
    """A bare whole-pixel length as an integer; an undeclared one, or a zero in
    any unit, as 0; and None for everything else. A var(), a calc(), a clamp(),
    a rem, a percentage or a viewport unit carrying a real number is not
    something a pixel budget can be checked against, so it reads as unusable and
    fails the check rather than being guessed at."""
    value = value.strip()
    if not value or _ZERO_RE.fullmatch(value):
        return 0
    m = _PX_RE.fullmatch(value)
    return int(m.group(1)) if m else None


_PX_NUMBER_RE = re.compile(r"(\d+(?:\.\d+)?)px")
_NUMBER_RE = re.compile(r"\d+(?:\.\d+)?")


def _px_number(value: str) -> float | None:
    """A pixel length as a number, fractional steps included — 16.5px reads as
    16.5. The same refusal as _px_length for anything that is not a plain pixel
    literal: a var(), a calc(), a clamp(), a rem or a viewport unit reads as
    None, so a step stated through a token whose value could be any expression
    fails the check that reads it instead of being guessed at."""
    m = _PX_NUMBER_RE.fullmatch(value.strip())
    return float(m.group(1)) if m else None


def _unitless(value: str) -> float | None:
    """A bare number — the way a line-height is stated — or None for anything
    carrying a unit, a var() or an expression."""
    return float(value) if _NUMBER_RE.fullmatch(value.strip()) else None


def _resolved(decls: list[dict[str, str]], prop: str) -> str:
    """What `prop` resolves to across `decls` in cascade order — the last rule
    that states it wins, the way the sheet's own cascade decides — or the empty
    string when no rule states it. The reader a negative control APPENDING an
    old value is judged through, so the control wins exactly as a real edit
    would."""
    value = ""
    for block in decls:
        if prop in block:
            value = _norm(block[prop])
    return value


def _restyled(css: str, selector: str, extra: str) -> str:
    """`selector`'s rule with `extra` appended to its declarations — the control
    for a frame that took back the room the budget forbids it. Appended rather
    than substituted so the cascade decides, exactly as a real edit would."""
    for prelude, body in _css_sections(css):
        if selector in [s.strip() for s in prelude.split(",")]:
            rule = prelude + "{" + body + "}"
            return css.replace(rule, prelude + "{" + body + ";" + extra + "}", 1)
    return css


_HEADING_NAME_RE = re.compile(r"h[1-6]")


def _headings(doc: str) -> list[str]:
    """Every heading start tag in `doc`, in document order — the outline as a
    reader's rotor walks it. Kept beside _tags_named for the same reason: the
    checks navigate structure, they do not match markup."""
    return [m.group(0) for m in re.finditer(r"<[a-zA-Z][^<>]*>", doc)
            if _HEADING_NAME_RE.fullmatch(_tag_name(m.group(0)))]


def _heading_level(tag: str) -> int:
    """A heading start tag's level, 1..6."""
    return int(_tag_name(tag)[1])


def _style_text(doc: str) -> str:
    """The stylesheet a rendered document actually carries: every <style> body,
    concatenated and comment-stripped. Read off the document rather than off the
    constant it was built from, so "this page ships these rules" is checked and
    not assumed."""
    return _strip_css_comments("\n".join(
        re.findall(r"<style[^>]*>(.*?)</style>", doc, flags=re.S)))


def _rendered_hooks(ctx: dict) -> set[str]:
    """Every data-kw hook that actually reaches a rendered document, static or
    bound. The population the coverage rule is measured against."""
    out: set[str] = set()
    pat = re.compile(r"[:@]?(" + re.escape(KW_PREFIX) + r"[\w-]+)")
    for key in _DOC_KEYS:
        for tag in re.finditer(r"<[a-zA-Z][^<>]*>", ctx[key]):
            out.update(pat.findall(tag.group(0)))
    return out


def _check_body(fn) -> str:
    """`fn`'s own body source, decorators excluded. Naming a hook in a
    registration is not reading it — only the code inside the check is."""
    try:
        src = textwrap.dedent(inspect.getsource(fn))
    except (OSError, TypeError):
        return ""
    tree = ast.parse(src)
    return "\n".join(ast.unparse(s) for s in tree.body[0].body) if tree.body else ""


def _hook_is_read(hook: str) -> bool:
    """Whether some registered check actually reads `hook` — as the element it
    binds to, or as an attribute it takes off that element."""
    word = re.compile(r"(?<![\w-])" + re.escape(hook) + r"(?![\w-])")
    return any(word.search(_check_body(e["fn"]))
               for e in _COVERAGE_REGISTRY.values())


_ATTR_RE = re.compile(r'([@:]?[A-Za-z_][\w:.\-]*)(?:\s*=\s*"([^"]*)")?')


def _attrs(tag: str) -> dict[str, str]:
    """A start tag's attributes as {name: value}; a valueless attribute maps to ""."""
    body = tag[1:-1].rstrip("/")
    body = body[len(_tag_name(tag)):]
    return {m.group(1): (m.group(2) or "") for m in _ATTR_RE.finditer(body)}


def _classes_in(doc: str) -> set[str]:
    """Every class name any start tag in `doc` carries. Lets a check ask "which
    elements in this subtree reach a given type role" without writing a markup
    fragment into the check itself."""
    out: set[str] = set()
    for tag in re.finditer(r"<[a-zA-Z][^<>]*>", doc):
        out.update(_attrs(tag.group(0)).get("class", "").split())
    return out


def _role_of(css: str, cls: str) -> set[str]:
    """The type-role variables the rules for `.cls` name as its font-family. An
    empty set means the class states no family and inherits one."""
    return {v for d in _decls_for(css, "." + cls)
            for v in _VAR_REF_RE.findall(d.get("font-family", ""))}


def _url_attr_exprs(doc: str) -> list[str]:
    """Every URL-bearing attribute value in `doc` — href/src/action/formaction,
    static or Vue-bound. The population a "no untrusted field reaches a URL"
    rule is measured against, so consuming a feed field as inert TEXT stays
    allowed while binding it into a navigable URL does not.

    Both of Vue's binding spellings are normalized, not just the shorthand. This
    page writes `:href` everywhere today, so a population built on `:` alone
    would have let a `v-bind:href` through — a gap that costs one regex to close
    now and would be invisible the day someone writes the long form."""
    urlish = ("href", "src", "action", "formaction", "xlink:href")
    out = []
    for tag in re.finditer(r"<[a-zA-Z][^<>]*>", doc):
        for name, value in _attrs(tag.group(0)).items():
            bare = re.sub(r"^(?::|@|v-bind:|v-on:)", "", name.strip()).lower()
            if bare in urlish:
                out.append(value)
    return out


def _class_binding(attrs: dict[str, str]) -> dict[str, str]:
    """Vue's `:class` object binding as {class name: the expression gating it}."""
    return {c: e.strip() for c, e in
            re.findall(r"'([^']+)'\s*:\s*([^,}]+)", attrs.get(":class", ""))}


def _first_index(doc: str, hook: str) -> int:
    tags = _tags_with(doc, hook)
    return doc.index(tags[0]) if tags else -1


def _inlined_state(doc: str) -> dict:
    """The state the document inlines for first paint (also what a file:// copy renders)."""
    m = re.search(r"window\.__HATCH_STATE__ = (.*?);window\.__HATCH_THEME__", doc, re.S)
    return json.loads(m.group(1)) if m else {}


def _inlined_repos(doc: str):
    """The roster the hub home inlines for its feeds, or None on a repo page."""
    m = re.search(r"window\.__HATCH_REPOS__ = (.*?);</script>", doc, re.S)
    return json.loads(m.group(1)) if m else None


def _inlined_const(doc: str, name: str):
    """A `const <name> = <json>;` the server hands the app (SHELL, FEED, …)."""
    m = re.search(r"const " + name + r" = (.*?);\n", doc)
    return json.loads(m.group(1)) if m else None


def _title_text(doc: str) -> str:
    tags = _tags_with(doc, "data-kw-title")
    if not tags:
        return ""
    start = doc.index(tags[0]) + len(tags[0])
    return doc[start:doc.index("<", start)]


def _text_in(doc: str, hook: str) -> str:
    """The text node the hook's element opens with — the interpolation, for a
    check that has to read WHICH field an element renders without quoting the
    surrounding markup back at itself."""
    tags = _tags_with(doc, hook)
    if not tags:
        return ""
    start = doc.index(tags[0]) + len(tags[0])
    return doc[start:doc.index("<", start)].strip()


_INTERPOLATION_RE = re.compile(r"\{\{\s*(.*?)\s*\}\}")


def _interpolated(text: str) -> str:
    """The expression a `{{ … }}` text node interpolates, or "" when the text is
    not exactly one interpolation."""
    found = _INTERPOLATION_RE.fullmatch(text.strip())
    return found.group(1) if found else ""


def _js_block(src: str, opener: str) -> str:
    """The `opener` line plus its brace-matched body."""
    i = src.find(opener)
    if i == -1:
        return ""
    j, depth = i + len(opener), 1
    while j < len(src) and depth:
        depth += 1 if src[j] == "{" else -1 if src[j] == "}" else 0
        j += 1
    return src[i:j]


def _css_sections(css: str) -> list[tuple[str, str]]:
    """Every top-level `<prelude>{<body>}` in `css`, brace-aware (at-rules nest)."""
    out, i, n = [], 0, len(css)
    while i < n:
        j = css.find("{", i)
        if j == -1:
            break
        depth, k = 1, j + 1
        while k < n and depth:
            depth += 1 if css[k] == "{" else -1 if css[k] == "}" else 0
            k += 1
        out.append((css[i:j].strip(), css[j + 1:k - 1]))
        i = k
    return out


def _css_rules(css: str) -> list[tuple[str, dict[str, str]]]:
    """Top-level style rules as (selector list, {property: value}); at-rules skipped."""
    rules = []
    for prelude, body in _css_sections(css):
        if prelude.startswith("@"):
            continue
        decls = {}
        for decl in body.split(";"):
            prop, sep, value = decl.partition(":")
            if sep:
                decls[prop.strip()] = value.strip()
        rules.append((prelude, decls))
    return rules


def _at_rule_body(css: str, needle: str) -> str:
    for prelude, body in _css_sections(css):
        if prelude.startswith("@") and needle in prelude:
            return body
    return ""


def _decls_for(css: str, selector: str) -> list[dict[str, str]]:
    """Declarations of every rule naming `selector` exactly in its selector list."""
    return [decls for sel, decls in _css_rules(css)
            if selector in [s.strip() for s in sel.split(",")]]


def _norm(value: str) -> str:
    return value.replace("!important", "").strip()


def _radius_declarations(css: str) -> list[tuple[str, str]]:
    """(selector, corner radius) for every rule in the sheet that declares one,
    one entry per selector in a grouped rule. Kept here rather than inline in a
    check for the same reason as the other readers: the checks read the sheet
    through the parser, they never match its text."""
    out = []
    for prelude, decls in _css_rules(css):
        if "border-radius" in decls:
            for sel in prelude.split(","):
                out.append((sel.strip(), _norm(decls["border-radius"])))
    return out


def _animates_with(decls: dict[str, str], keyframe: str) -> bool:
    return keyframe in _norm(decls.get("animation", "")).split()


def _strip_css_comments(css: str) -> str:
    return re.sub(r"/\*.*?\*/", "", css, flags=re.S)


def _palette_decls(css: str, selector: str) -> dict[str, str]:
    """The palette declarations of `selector`, keyed on the rule that defines
    --bg. The sheet carries more than one `:root` rule — the palette, and the
    theme-independent type roles — so "the palette one" needs a marker, and the
    page ground is the one token a palette cannot be missing."""
    for decls in _decls_for(css, selector):
        if "--bg" in decls:
            return {k: v for k, v in decls.items() if k.startswith("--")}
    return {}


def _reduced_block(css: str) -> str:
    return _at_rule_body(css, "prefers-reduced-motion")


def _drop_reduced_rule(css: str, selector: str) -> str:
    """The stylesheet with `selector`'s reduced-motion rule removed — the control
    for "this motion was left with no stated reduced-motion behaviour"."""
    body = _reduced_block(css)
    kept = "".join("%s{%s}" % (prelude, inner)
                   for prelude, inner in _css_sections(body)
                   if selector not in [s.strip() for s in prelude.split(",")])
    return css.replace(body, kept)


# var(--x) as it appears in a stylesheet, an inline style, or a metadata value.
_VAR_REF_RE = re.compile(r"var\(\s*(--[a-z0-9-]+)")
_VAR_DEF_RE = re.compile(r"(--[a-z0-9-]+)\s*:")


def _vendored_weights() -> dict[str, set[int]]:
    """family -> the weights this plugin actually ships a file for.

    This is the ONE place a VENDORED_FACES weight RANGE becomes integers. A
    variable face shipped as a single file covers a span of weights, and every
    reader of this map asks the same integer question — "is there a file behind
    the font-weight this rule wrote" — so the range is expanded here rather than
    at each of the six call sites, two of which would silently accept a tuple
    into a set of ints and then never match anything.

    The step is 100 because the page's own scale is: the design asks for whole
    hundreds, so Plus Jakarta Sans's 400..800 reports {400, 500, 600, 700, 800}.
    A rule asking for 450 is a weight this page does not use, and failing it is
    the conservative direction — the file would render it, but nothing in the
    design calls for it and an unexplained 450 is more likely a typo."""
    out: dict[str, set[int]] = {}
    for family, weight in VENDORED_FACES:
        low, high = weight if isinstance(weight, tuple) else (weight, weight)
        out.setdefault(family, set()).update(range(low, high + 1, 100))
    return out


_ROLE_FAMILY = {"--mono": "IBM Plex Mono", "--sans": "Plus Jakarta Sans"}

# The families the Hatch Status design dropped, and the family that took over
# each one's text. Recorded rather than merely deleted, like _RETIRED_TOKENS, so
# vendored-typefaces-named-as-shipped can hold every surface to their absence.
_RETIRED_FAMILIES: dict[str, str] = {"Newsreader": "Plus Jakarta Sans",
                                     "IBM Plex Sans": "Plus Jakarta Sans"}


class _Ns:
    """A stand-in for the handler collaborators a direct method call needs."""

    def __init__(self, **kw):
        self.__dict__.update(kw)


def _renamed(ctx: dict, hook: str, *doc_keys: str) -> dict:
    """A context whose `hook` is renamed in `doc_keys` — the RENAMING control."""
    return {k: ctx[k].replace(hook, hook + "renamed") for k in doc_keys}


def _moved_inside(ctx: dict, hook: str, into: str) -> dict:
    """A page whose `hook` element has been moved bodily inside the element
    carrying `into` — the control for "this block was left inside the control the
    design took it out of"."""
    page = ctx["page"]
    block = _subtree(page, _tags_with(page, hook)[0])
    host = _tags_with(page, into)[0]
    return {"page": page.replace(block, "", 1).replace(host, host + block, 1)}


def _retagged(ctx: dict, hook: str, name: str, *doc_keys: str) -> dict:
    """A document whose `hook` element opens as `name` instead — the control for
    a heading that was never made one, or made one where the design heads
    nothing. Only the START tag moves, which is the whole of what an outline
    reader sees: every structural reader here works off start tags, so that is
    where a tag claim is read from and where a control has to lie."""
    out = {}
    for key in doc_keys:
        doc = ctx[key]
        tag = _tags_with(doc, hook)[0]
        out[key] = doc.replace(tag, "<" + name + tag[1 + len(_tag_name(tag)):], 1)
    return out


# --- the registry: one entry per behaviour that must never disappear ---------

@_covers("page-title-repo-name", kind="rendered", hook="data-kw-title",
         breaks=[lambda c: _renamed(c, "data-kw-title", "page"),
                 lambda c: {"page": c["page"].replace(c["repo_name"], "other")}])
def _c_page_title(ctx):
    tags = _tags_with(ctx["page"], "data-kw-title")
    if len(tags) != 1 or _tag_name(tags[0]) != "title":
        return False
    name = _attrs(tags[0]).get("data-kw-repo-name", "")
    return (name == ctx["repo_name"] == ctx["shell_hub"].get("name")
            and ctx["title_suffix"] == ctx["wordmark"]
            and _title_text(ctx["page"]) == name + " — " + ctx["title_suffix"]
            and _title_text(ctx["eph"]) == "hatch — " + ctx["title_suffix"])


@_covers("shell-home-link", kind="rendered", hook="data-kw-shell-home",
         breaks=[lambda c: _renamed(c, "data-kw-shell-home", "page"),
                 lambda c: {"shell_hub": dict(c["shell_hub"], home=None)}])
def _c_shell_home_link(ctx):
    tags = _tags_with(ctx["page"], "data-kw-shell-home")
    if len(tags) != 1 or _tag_name(tags[0]) != "a":
        return False
    attrs = _attrs(tags[0])
    home = ctx["shell_hub"].get("home") or ""
    return (attrs.get(":href") == "shell.home"
            and attrs.get("v-if") == "shell.home"
            and home.startswith("/") and ctx["key_token"] in home)


@_covers("shell-repo-name", kind="rendered", hook="data-kw-shell-repo",
         breaks=[lambda c: _renamed(c, "data-kw-shell-repo", "page"),
                 lambda c: {"shell_hub": dict(c["shell_hub"], name="a/path/name")}])
def _c_shell_repo_name(ctx):
    tags = _tags_with(ctx["page"], "data-kw-shell-repo")
    if len(tags) != 1:
        return False
    cls = _attrs(tags[0]).get("class", "")
    name = ctx["shell_hub"].get("name") or ""
    return (bool(_decls_for(ctx["css"], "." + cls))
            and name == ctx["repo_name"] and "/" not in name)


@_covers("shell-feed-indicator", kind="rendered", hook="data-kw-feed",
         breaks=[lambda c: _renamed(c, "data-kw-feed", "page"),
                 lambda c: {"feed_labels": {"live": "x", "paused": "y"}},
                 lambda c: {"feed_inlined": {"live": "x", "paused": "y"}}])
def _c_shell_feed_indicator(ctx):
    tags = _tags_with(ctx["page"], "data-kw-feed")
    if len(tags) != 1:
        return False
    attrs = _attrs(tags[0])
    paused = attrs.get(":data-kw-feed-paused", "")
    gated = _class_binding(attrs)
    return (bool(gated) and any(expr and expr in paused for expr in gated.values())
            and ctx["feed_inlined"] == ctx["feed_labels"])


# --- the page frame: header, running-now strip, footer, views ----------------
#
# The Hatch Status design's frame (template L303-333, L629-632): a slim header
# that scrolls with the page, a running-now strip on every view while something
# builds, and a two-line footer — around views the page moves between. The map
# rail, the show-delivered toggle, the mascot and the header's branch chips are
# gone, and each absence is a claim of its own below, so none of them can come
# back without a check turning red.

def _doc_title(doc: str) -> str:
    """The text of a document's <title>, whichever hooks it carries."""
    tags = _tags_named(doc, "title")
    if len(tags) != 1:
        return ""
    start = doc.index(tags[0]) + len(tags[0])
    return doc[start:doc.index("<", start)]


def _with_hook_inserted(doc: str, after_hook: str, element: str, hook: str) -> str:
    """A document with an empty `element` carrying `hook` put just inside the
    element carrying `after_hook` — the control for a surface coming back."""
    host = _tags_with(doc, after_hook)[0]
    return doc.replace(host, host + "<" + element + " " + hook + "></" + element + ">", 1)


@_covers("header-region-holds-brand-feed-and-controls", kind="rendered",
         hook="data-kw-header",
         breaks=[lambda c: _renamed(c, "data-kw-header", "page"),
                 lambda c: _moved_inside(c, "data-kw-theme-toggle", "data-kw-main"),
                 lambda c: _moved_inside(c, "data-kw-hat-legend", "data-kw-main"),
                 lambda c: {"css": c["css"].replace(
                     "padding:12px 18px;", "padding:0 34px 56px;", 1)},
                 lambda c: {"css": _restyled(c["css"], ".hdr",
                                             "position:sticky; top:0")},
                 lambda c: {"css": _restyled(c["css"], ".wrap", "max-width:1440px")},
                 # the mount sized by its content again: the frame narrows to
                 # whatever a view holds
                 lambda c: {"css": _restyled(c["css"], "#app", "width:auto")},
                 # a short detail view's frame stopping short of the footer
                 lambda c: {"css": _restyled(c["css"], ".dframe", "flex:none")},
                 # the frame growing from a 0% basis, which drops home's fixed
                 # height and lets the four squares spill past the viewport
                 lambda c: {"css": _restyled(c["css"], ".wrap", "flex:1")}])
def _c_header_region(ctx):
    """The header is the page's one header region and it opens the frame: the
    first thing inside the 1280 measure, which sits in the body's 12px 18px
    padding — the design's root. It holds the brand (the egg control, the
    wordmark, the repo name), the live dot, both refresh controls, the theme
    toggle and the HAT legend, each INSIDE it rather than merely on the page.
    And it does not stick: the design's slim header scrolls with the page.

    The measure is the viewport's and never a view's content: the Vue mount
    `#app` resolves to width 100%, so the frame's width:100% reads the body's
    content box. And the frame reaches the footer on every view: `#app` and
    `.wrap` grow from an auto basis (flex 1 0 auto, so home's fixed height
    still holds), and `.main` and the detail frame `.dframe` resolve to flex
    1, as the design's detail frame fills its 100vh root."""
    page, css = ctx["page"], ctx["css"]
    tags = _tags_with(page, "data-kw-header")
    if len(tags) != 1 or _tag_name(tags[0]) != "header":
        return False
    if "data-kw-shell" not in _attrs(tags[0]):
        return False
    wraps = [t for t in _start_tags(page) if "wrap" in _attrs(t).get("class", "").split()]
    if len(wraps) != 1 or _child_tags(page, wraps[0])[:1] != tags:
        return False
    region = _subtree(page, tags[0])
    held = ("data-kw-brand", "data-kw-wordmark", "data-kw-shell-repo",
            "data-kw-feed", "data-kw-refresh-now", "data-kw-auto-refresh",
            "data-kw-theme-toggle", "data-kw-hat-legend")
    if not all(_tags_with(region, h) for h in held):
        return False
    rules = _rules_for_tag(css, tags[0])
    if any(_norm(d.get("position", "")) in ("sticky", "fixed") for d in rules):
        return False
    body = _decls_for(css, "body")
    frame = _rules_for_tag(css, wraps[0])
    return ([_px_length(_box_side(body, "padding", s))
             for s in ("top", "right", "bottom", "left")] == [12, 18, 12, 18]
            and _px_length(_resolved(frame, "max-width")) == 1280
            and _resolved(_decls_for(css, "#app"), "width") == "100%"
            and all(_resolved(_decls_for(css, sel), "flex") == "1 0 auto"
                    for sel in ("#app", ".wrap"))
            and all(_resolved(_decls_for(css, sel), "flex") == "1"
                    for sel in (".main", ".dframe")))


def _root_member_names(app: str) -> tuple[set, set]:
    """The root component's data keys — the top-level keys of the object its
    data() returns, at that object's own indent — and the names its computed
    and methods blocks define at theirs (`name() {` or a bare `name,`)."""
    root = _js_block(app, "const app = createApp({")
    data = _js_block(_js_block(root, "  data() {"), "    return {")
    keys = set(re.findall(r"^      ([A-Za-z_$][\w$]*):", data, re.M))
    defined = set()
    for opener in ("  computed: {", "  methods: {"):
        block = _js_block(root, opener)
        defined |= set(re.findall(r"^    ([A-Za-z_$][\w$]*)(?:\(|,)", block, re.M))
    return keys, defined


@_covers("root-data-never-shadows-a-computed-or-method", kind="behaviour",
         breaks=[# the shadowing status-fidelity-gate found: the item card's
                 # wording kept under `card`, the name of the next-step computed
                 lambda c: {"app_src": c["app_src"].replace(
                     "      cardWords: DETAIL.card,", "      card: DETAIL.card,", 1)},
                 # a data key shadowing a method
                 lambda c: {"app_src": c["app_src"].replace(
                     "      feeds: feeds,", "      feeds: feeds,\n      go: null,", 1)}])
def _c_root_data_never_shadows(ctx):
    """No key of the root component's data() is also the name of one of its
    computed properties or methods. Vue's template proxy reads data before
    computed and methods, so a shared name silently hides the computed: the
    build view's next-step card once read the item card's wording object as
    `card`, and lost its tag and its where-to-run line with no error. Read off
    the source with _root_member_names; both sets must be non-empty, so a
    reader that stopped finding the blocks fails rather than passing."""
    keys, defined = _root_member_names(ctx["app_src"])
    return bool(keys) and bool(defined) and not (keys & defined)


@_covers("no-rail-on-the-page", kind="behaviour",
         breaks=[lambda c: {"page": _with_hook_inserted(c["page"], "data-kw-main",
                                                        "aside", "data-kw-rail")},
                 lambda c: {"css": c["css"] + "\n.rail{ display:grid; }"},
                 lambda c: {"app_src": c["app_src"] + "\nfunction railGroupsOf(b) { return []; }"},
                 lambda c: {"eph": _with_hook_inserted(c["eph"], "data-kw-main",
                                                       "button", "data-kw-pick")}])
def _c_no_rail(ctx):
    """There is no map rail anywhere: no rail, pick or split hook in any document
    the page renders, no aside, no rule left in the sheet for a rail or the
    two-column split it sat in, and none of the rail's selection logic left in
    the app. The binder the page shows is no longer picked on a map — the
    binder view shows the build that was opened, and the home view lists every
    build in one place, its My builds square (home-is-four-squares)."""
    gone = ("data-kw-rail", "data-kw-pick", "data-kw-split")
    for key in _DOC_KEYS:
        doc = ctx[key]
        if _tags_named(doc, "aside"):
            return False
        for tag in _start_tags(doc):
            if any(name.lstrip(":").startswith(gone) for name in _attrs(tag)):
                return False
    selectors = [sel.strip() for prelude, _ in _css_rules(ctx["css"])
                 for sel in prelude.split(",")]
    if any(re.match(r"\.(rail|split)(?![\w-])|\.(rail|split)__", s) for s in selectors):
        return False
    app = ctx["app_src"]
    return not any(word in app for word in ("railGroupsOf", "railSelectionOf",
                                            "pickAfterFilter", "RAIL."))


@_covers("no-show-delivered-toggle", kind="behaviour",
         breaks=[lambda c: {"app_src": c["app_src"]
                            + "\nlocalStorage.getItem('hatch-show-delivered');"},
                 lambda c: {"page": _with_hook_inserted(c["page"], "data-kw-header",
                                                        "button", "data-kw-show-delivered")},
                 lambda c: {"hub": c["hub"].replace("</body>",
                                                    "<script>var showDelivered;</script></body>")}])
def _c_no_show_delivered(ctx):
    """The show-delivered toggle is gone, and so is its preference: no document
    carries the control's hook or its label hook, and the persisted
    hatch-show-delivered key is neither read nor written by anything the page
    ships — an existing stored value is simply ignored, not migrated."""
    for key in _DOC_KEYS:
        doc = ctx[key]
        if "hatch-show-delivered" in doc or "showDelivered" in doc:
            return False
        if _tags_with(doc, "data-kw-show-delivered") or _tags_with(doc, "data-kw-delivered-label"):
            return False
    return "hatch-show-delivered" not in ctx["app_src"]


@_covers("only-view-titles-are-headed", kind="behaviour",
         breaks=[lambda c: _retagged(c, "data-kw-hat-legend", "h2", "page"),
                 lambda c: _retagged(c, "data-kw-next-eyebrow", "h2", "page"),
                 lambda c: _retagged(c, "data-kw-wave-step-label", "h3", "page"),
                 lambda c: _retagged(c, "data-kw-running-strip", "h2", "page"),
                 lambda c: _retagged(c, "data-kw-shell-repo", "h2", "eph"),
                 lambda c: _retagged(c, "data-kw-wave-legend", "h3", "page")])
def _c_only_view_titles_headed(ctx):
    """No heading is invented for anything the design leaves unheaded. The
    page's whole outline is the wordmark and the view titles under it — the
    Builds and Wave map sections' titles and the shown build's — so the repo
    name, the HAT legend, the strip, the next-step card's eyebrow, every wave
    frame's mode word, the wave map's legend and the footer all stay the plain
    elements they are, in every state the page renders in."""
    for key in _APP_DOC_KEYS:
        doc = ctx[key]
        for hook in ("data-kw-shell-repo", "data-kw-hat-legend",
                     "data-kw-running-strip", "data-kw-next-eyebrow",
                     "data-kw-wave-step-label", "data-kw-wave-legend"):
            if any(t in _headings(doc) for t in _tags_with(doc, hook)):
                return False
        feet = _tags_with(doc, "data-kw-footer")
        if len(feet) != 1 or _headings(_subtree(doc, feet[0])):
            return False
        allowed = (_tags_with(doc, "data-kw-wordmark") + _tags_with(doc, "data-kw-binder-heading")
                   + _tags_with(doc, "data-kw-view-title"))
        if set(_headings(doc)) != set(allowed):
            return False
    return True


@_covers("one-top-level-heading-is-the-wordmark", kind="behaviour",
         breaks=[lambda c: _retagged(c, "data-kw-wordmark", "span", "page"),
                 lambda c: _retagged(c, "data-kw-binder-heading", "h1", "page"),
                 lambda c: {"empty_page": c["empty_page"].replace(
                     c["wordmark"] + "</h1>", "Hatch <b>Status</b></h1>", 1)},
                 lambda c: _retagged(c, "data-kw-wordmark", "div", "hub_empty"),
                 lambda c: {"wordmark": "Hatch status"}])
def _c_wordmark_heading(ctx):
    """The wordmark is the page's one top-level heading on every page: in each
    state the repo page renders in, exactly one h1, it opens the outline, and it
    reads 'Hatch Status' in normal capitals as ONE text run — no element inside
    it splitting the name the way the design's two-tone mark does. The hub home
    is the same document, so it heads itself the same way and no page goes
    unnamed."""
    word = ctx["wordmark"]
    if word != "Hatch Status":
        return False
    for key in _APP_DOC_KEYS:
        doc = ctx[key]
        marks = _tags_with(doc, "data-kw-wordmark")
        heads = _headings(doc)
        tops = [t for t in heads if _heading_level(t) == 1]
        if len(marks) != 1 or tops != marks or heads[:1] != marks:
            return False
        if _subtree(doc, marks[0]) != marks[0] + word + "</h1>":
            return False
    return True


@_covers("egg-is-the-only-brand-mark", kind="behaviour",
         breaks=[lambda c: {"page": c["page"].replace(
                     "data-kw-wordmark", 'data-kw-wordmark><img src="/assets/mascot.png"', 1)},
                 lambda c: {"eph": c["eph"].replace("go('home')", "refreshNow()", 1)},
                 lambda c: {"hub": c["hub"].replace(_ICON_VIEWBOX["egg"], "0 0 24 24")},
                 lambda c: {"css": c["css"] + "\n@keyframes hatch-draw{ to{ stroke-dashoffset:0; } }"},
                 lambda c: {"asset_files": [f for f in c["asset_files"] if f != "mascot.png"]},
                 lambda c: {"page": c["page"].replace(
                     'aria-label="' + c["brand_home"] + '"', 'aria-label="hatch watch hub"', 1)}])
def _c_egg_only_brand(ctx):
    """The egg is the brand, and the only one. On a repo page it is the control
    that goes home — a keyed link to the hub home on a hub repo page, a button
    back to this page's home view anywhere else — drawn with the egg glyph and
    named 'Hatch Status home', and the hub home hands its app the egg's own
    canvas exactly as a repo page does. No
    document renders the mascot image or the old k-mark, mascot or underline
    hooks, and the draw keyframe that underline wore is gone from the sheet. The
    mascot file itself stays on disk and on its asset route for the README."""
    page, label = ctx["page"], ctx["brand_home"]
    marks = _tags_with(page, "data-kw-brand")
    if len(marks) != 2:
        return False
    link = [t for t in marks if _tag_name(t) == "a"]
    button = [t for t in marks if _tag_name(t) == "button"]
    if len(link) != 1 or len(button) != 1:
        return False
    if (_attrs(link[0]).get("v-if") != "shell.home"
            or _attrs(link[0]).get(":href") != "shell.home"
            or "v-else" not in _attrs(button[0])
            or _attrs(button[0]).get("@click") != "go('home')"):
        return False
    for tag in marks:
        if _attrs(tag).get("aria-label") != label or label != ctx["wordmark"] + " home":
            return False
        inner = [_attrs(t).get("name") for t in _tags_named(_subtree(page, tag), "icon")]
        if inner != ["egg"]:
            return False
    for key in _APP_DOC_KEYS:
        eph_marks = _tags_with(ctx[key], "data-kw-brand")
        if [_attrs(t).get("@click") for t in eph_marks if _tag_name(t) == "button"] != ["go('home')"]:
            return False
    for key in _DOC_KEYS:
        doc = ctx[key]
        if any("mascot" in _attrs(t).get("src", "") for t in _tags_named(doc, "img")):
            return False
        if any(_tags_with(doc, h) for h in ("data-kw-shell-kmark", "data-kw-shell-mascot",
                                            "data-kw-shell-underline", "data-kw-empty-mascot")):
            return False
    for key in ("hub", "hub_all", "hub_empty"):
        box = _inlined_const(ctx[key], "ICON_VIEWBOX") or {}
        if box.get("egg") != ctx["icon_viewbox"]["egg"]:
            return False
    if "hatch-draw" in ctx["css"]:
        return False
    return "mascot.png" in ctx["asset_files"] and ctx["asset_probe"]("/assets/mascot.png") == 200


@_covers("no-branch-chips-in-the-header", kind="behaviour",
         breaks=[lambda c: {"page": _with_hook_inserted(c["page"], "data-kw-header",
                                                        "span", "data-kw-branch-chip")},
                 lambda c: {"app_src": c["app_src"] + "\nfunction branchChips(state) { return []; }"},
                 lambda c: {"page": c["page"].replace(
                     "data-kw-hat-legend>", 'data-kw-hat-legend><icon name="branch" />', 1)}])
def _c_no_branch_chips(ctx):
    """The design's header carries no branch chips, so the page's header carries
    none: no chip hook, no branch glyph inside the header, and none of the chip
    logic left in the app. The real branch names still render, in the build
    view's own header chip and its meta line."""
    page = ctx["page"]
    heads = _tags_with(page, "data-kw-header")
    if len(heads) != 1:
        return False
    region = _subtree(page, heads[0])
    for tag in _start_tags(region):
        if any(name.lstrip(":").startswith("data-kw-branch-chip") for name in _attrs(tag)):
            return False
        if _tag_name(tag) == "icon" and _attrs(tag).get("name") == "branch":
            return False
    return "branchChips" not in ctx["app_src"] and bool(_tags_with(page, "data-kw-binder-meta"))


@_covers("empty-state-shows-the-egg", kind="rendered", hook="data-kw-empty-egg",
         breaks=[lambda c: _renamed(c, "data-kw-empty-egg", "empty_page"),
                 lambda c: {"empty_page": c["empty_page"].replace(
                     'name="egg" :size="56"', 'name="check" :size="56"', 1)},
                 lambda c: {"empty_page": _moved_inside(dict(c, page=c["empty_page"]),
                                                        "data-kw-empty-egg",
                                                        "data-kw-header")["page"]}])
def _c_empty_state_egg(ctx):
    """With no binder planned, the empty state shows the egg: one egg glyph,
    inside the empty section, which is still the branch the page renders when
    the feed holds no builds — and no image of any kind in it."""
    page = ctx["empty_page"]
    section = _tags_with(page, "data-kw-empty")
    eggs = _tags_with(page, "data-kw-empty-egg")
    if len(section) != 1 or len(eggs) != 1:
        return False
    block = _subtree(page, section[0])
    if eggs[0] not in block or _tags_named(block, "img"):
        return False
    glyphs = [_attrs(t).get("name") for t in _tags_named(_subtree(page, eggs[0]), "icon")]
    return (glyphs == ["egg"] and "v-else" in _attrs(section[0])
            and _inlined_state(page).get("binders") == [])


@_covers("favicon-is-the-egg-on-every-document", kind="behaviour",
         breaks=[lambda c: {"page": re.sub(r'<link rel="icon"[^>]*>',
                                           '<link rel="icon" type="image/png" href="/assets/mascot.png">',
                                           c["page"], count=1)},
                 lambda c: {"hub_empty": re.sub(r'<link rel="icon"[^>]*>', "", c["hub_empty"], count=1)},
                 lambda c: {"eph": c["eph"].replace("%23F5A623", "%23000000", 1)}])
def _c_favicon_egg(ctx):
    """Every document the page serves — the repo page in each state and the hub
    home over each of its rosters — carries one favicon, and it is the egg: an SVG
    data: URI drawn from the egg's own paths on its own canvas, in the design's
    ink and HAT gold. A data: URI needs no asset route and no key, so the tab
    icon cannot 403 on a hub page whose key was dropped."""
    want = [d["d"] for _tag, d in ctx["icons"]["egg"]]
    colours = {ctx["palette"][role]["light"] for role in ("--ink", "--hat")}
    for key in _DOC_KEYS:
        icons = [t for t in _tags_named(ctx[key], "link")
                 if _attrs(t).get("rel") == "icon"]
        if len(icons) != 1:
            return False
        attrs = _attrs(icons[0])
        href = html.unescape(attrs.get("href", ""))
        if attrs.get("type") != "image/svg+xml" or not href.startswith("data:image/svg+xml,"):
            return False
        svg = unquote(href.partition(",")[2])
        if ctx["icon_viewbox"]["egg"] not in svg or not all(d in svg for d in want):
            return False
        if not all(c in svg for c in colours) or "var(" in svg:
            return False
    return True


@_covers("every-document-is-titled-hatch-status", kind="behaviour",
         breaks=[lambda c: {"hub": c["hub"].replace(
                     ">" + c["wordmark"] + "</title>", ">Hatch Watch</title>", 1)},
                 lambda c: {"degraded_page": c["degraded_page"].replace(
                     " — " + c["wordmark"] + "</title>", "</title>", 1)},
                 lambda c: {"title_suffix": "Hatch Watch"}])
def _c_titled_hatch_status(ctx):
    """The tab names the product on every document: '<repo> — Hatch Status' on
    each state of a repo page, empty and degraded included, and 'Hatch Status'
    alone on the hub home, which shows no one repo, over each of its rosters."""
    word, name = ctx["wordmark"], ctx["repo_name"]
    if ctx["title_suffix"] != word:
        return False
    for key in ("empty_page", "degraded_page"):
        if _doc_title(ctx[key]) != name + " — " + word:
            return False
    if _doc_title(ctx["page"]) != name + " — " + word or _doc_title(ctx["eph"]) != "hatch — " + word:
        return False
    return all(_doc_title(ctx[k]) == word for k in ("hub", "hub_all", "hub_empty"))


@_covers("retired-wording-renders-nowhere", kind="behaviour",
         breaks=[lambda c: {"page": c["page"].replace("</body>", "Hatch Watch</body>", 1)},
                 lambda c: {"hub_empty": c["hub_empty"].replace("</body>", "mirrors git</body>", 1)},
                 lambda c: {"retired_wording": dict(c["retired_wording"],
                                                    **{"jump to one": "a phrase nobody renders"})},
                 lambda c: {"eph": c["eph"].replace("</body>", "hatch watch hub</body>", 1)}])
def _c_retired_wording(ctx):
    """Every retired phrase is gone from every document the self-test builds —
    the repo page in each state and the hub home over each of its rosters — in any
    casing, so the old name renders nowhere. And each phrase that took one over
    renders somewhere, escaped as the page renders it, so the table can never
    name a destination the page does not show: the page's name, and the footer's
    two lines that now say what the rail's hint and the old footer used to."""
    docs = [ctx[k] for k in _DOC_KEYS]
    for old, new in ctx["retired_wording"].items():
        if any(old.lower() in doc.lower() for doc in docs):
            return False
        if not any(html.escape(new) in doc for doc in docs):
            return False
    return ctx["retired_wording"].get("Hatch Watch") == ctx["wordmark"]


@_covers("hat-legend-reads-the-design", kind="rendered", hook="data-kw-hat-legend",
         breaks=[lambda c: _renamed(c, "data-kw-hat-legend", "page"),
                 lambda c: {"css": c["css"].replace(".hat--lg{", ".hat--xl{")},
                 lambda c: {"frame_inlined": dict(c["frame_inlined"], hat_word="HATCH")},
                 lambda c: {"app_src": c["app_src"].replace(
                     "props: { size: { type: String, default: 'sm' } },", "", 1)}])
def _c_hat_legend(ctx):
    """The header's HAT legend reads as the design draws it: the HAT chip, then
    '= Human Attention needed', inside the header. The chip is ONE component
    with a size prop — sm, md and lg, each a modifier rule in the sheet — and it
    draws the person glyph and the word, on the HAT role with the HAT's own
    foreground, its meaning as its title."""
    page, css, words = ctx["page"], ctx["css"], ctx["frame_words"]
    tags = _tags_with(page, "data-kw-hat-legend")
    heads = _tags_with(page, "data-kw-header")
    if len(tags) != 1 or len(heads) != 1 or tags[0] not in _subtree(page, heads[0]):
        return False
    region = _subtree(page, tags[0])
    chips = _tags_named(region, "hat-chip")
    if len(chips) != 1 or _attrs(chips[0]).get("size") != "sm":
        return False
    if words["legend"] not in region or words["hat"] + " " + words["legend"] != "HAT = " + words["hat_meaning"]:
        return False
    inlined = ctx["frame_inlined"] or {}
    if inlined.get("hat_word") != words["hat"] or inlined.get("hat_meaning") != words["hat_meaning"]:
        return False
    chip_src = _js_block(ctx["app_src"], "const HatChip = " + chr(123))
    if "size:" not in chip_src or "type: String" not in chip_src or "data-kw-hat" not in chip_src:
        return False
    if "name=" + chr(34) + "person" + chr(34) not in chip_src:
        return False
    if not all(_decls_for(css, ".hat--" + s) for s in ("sm", "md", "lg")):
        return False
    base = _decls_for(css, ".hat")
    return (bool(base) and _resolved(base, "background") == "var(--hat)"
            and _resolved(base, "color") == "var(--on-hat)")


_STRIP_FIXTURE = [
    {"slug": "s-run", "title": "A running build", "status": "in_flight",
     "items": {"total": 3, "detail": [
         {"id": "a", "status": "done", "deps": []},
         {"id": "b", "status": "building", "deps": ["a"]},
         {"id": "c", "status": "ready", "deps": []}]}},
    {"slug": "s-two-waves", "title": None, "status": "in_flight",
     "items": {"total": 2, "detail": [
         {"id": "a", "status": "building", "deps": []},
         {"id": "b", "status": "building", "deps": ["a"]}]}},
    {"slug": "s-idle", "title": "Nothing building", "status": "not_started",
     "items": {"total": 1, "detail": [{"id": "a", "status": "ready", "deps": []}]}},
]


@_covers("running-strip-renders-only-while-something-builds", kind="rendered",
         hook="data-kw-running-strip",
         breaks=[lambda c: _renamed(c, "data-kw-running-strip", "page"),
                 lambda c: {"page": c["page"].replace('v-if="strip.length"', 'v-if="true"', 1)},
                 lambda c: {"running_strip": lambda b: [
                     {"slug": x["slug"], "name": x["slug"], "waves": ["W1"]} for x in b]},
                 lambda c: {"page": c["page"].replace("go('open', p.slug, p.repo)", "go('home')", 1)},
                 lambda c: _moved_inside(c, "data-kw-running-strip", "data-kw-main")])
def _c_running_strip(ctx):
    """The running-now strip renders on every view — between the header and the
    view's own column, outside any view — and only while some build has an item
    building. One pill per such build, named by its title (its slug in title
    case when it has none), carrying a W<n> chip for each wave that holds a
    building item; a click opens that build's binder view. Driven through the
    Python twin over builds built here, since the pinned fixture holds one
    shape: a build building in its second wave, a build building in both, and a
    build with nothing building, which gets no pill."""
    page = ctx["page"]
    strips = _tags_with(page, "data-kw-running-strip")
    heads = _tags_with(page, "data-kw-header")
    mains = _tags_with(page, "data-kw-main")
    if len(strips) != 1 or len(heads) != 1 or len(mains) != 1:
        return False
    if _attrs(strips[0]).get("v-if") != "strip.length":
        return False
    if strips[0] in _subtree(page, mains[0]) or strips[0] in _subtree(page, heads[0]):
        return False
    if not page.index(heads[0]) < page.index(strips[0]) < page.index(mains[0]):
        return False
    pills = _tags_with(page, "data-kw-strip-pill")
    waves = _tags_with(page, "data-kw-strip-wave")
    if len(pills) != 1 or len(waves) != 1 or waves[0] not in _subtree(page, pills[0]):
        return False
    pill = _attrs(pills[0])
    if (pill.get("v-for") != "p in strip" or pill.get("@click") != "go('open', p.slug, p.repo)"
            or pill.get(":data-kw-strip-slug") != "p.slug"
            or _attrs(waves[0]).get("v-for") != "w in p.waves"):
        return False
    strip = ctx["running_strip"]
    return (strip(_STRIP_FIXTURE) == [
                {"slug": "s-run", "name": "A running build", "waves": ["W2"]},
                {"slug": "s-two-waves", "name": "S Two Waves", "waves": ["W1", "W2"]}]
            and strip(_STRIP_FIXTURE[2:]) == [] and strip([]) == []
            and ctx["frame_inlined"].get("wave_fmt") == ctx["frame_words"]["wave_fmt"])


@_covers("frame-mirrors-match-their-twins", kind="behaviour",
         breaks=[lambda c: {"app_src": c["app_src"].replace(
                     "if (w.some(it => it.status === 'building'))", "if (true)", 1)},
                 lambda c: {"app_src": c["app_src"].replace(
                     "function runningStripOf(binders) {",
                     "function runningStripOf(binders) { return [];", 1)},
                 lambda c: {"app_src": c["app_src"].replace(
                     "if (nav.view === 'binder' && nav.from !== 'home') out.view = nav.from;",
                     "out.view = nav.from;", 1)},
                 lambda c: {"app_src": c["app_src"].replace(
                     "b => b.status === 'in_flight', ", "", 1)},
                 lambda c: {"app_src": c["app_src"].replace(
                     "if (failing || !auto || !visible) return 'paused';",
                     "if (failing) return 'paused';", 1)},
                 lambda c: {"py_twins": dict(c["py_twins"], view_after="def view_after(): pass")}])
def _c_frame_mirrors(ctx):
    """The page ships its own copies of the frame's four rules — the strip, the
    default build, the view state and the live dot — each the twin of a Python
    function the checks above drive. Checked the way this file's other twins
    are: the fragments that carry each decision present in the extracted body,
    the first statement anchored right after the opening brace so a stub put in
    front of the real body is caught, and the MIRROR marker on both sides. This
    reads final text; it does not claim to know what edit produced it."""
    app, py = ctx["app_src"], ctx["py_twins"]
    want = {
        "function runningStripOf(binders) {": ("const $VAR$ = [];", (
            "wavesOf(detail)", "it.status === 'building'", "FRAME.wave_fmt",
            "titleCase(b.slug)")),
        "function defaultBuildOf(binders) {": ("const $VAR$ = (binders || []).filter(", (
            "b.status === 'in_flight'", "b.status !== 'merged'", "() => true")),
        "function viewAfter(nav, action, slug) {": ("const $VAR$ = Object.assign({}, nav);", (
            "if (nav.view === 'binder' && nav.from !== 'home') out.view = nav.from;",
            "out.from = nav.view === 'binder' ? nav.from : nav.view;",
            "out.openItem = null", "FRAME.views.indexOf(action)")),
        "function backLabelOf(nav) {": ("if ($VAR$.view === 'binder'", ("FRAME.back_home",)),
        "function feedStateOf(snapshot, failing, auto, visible) {": ("if ($VAR$) return 'snapshot';", (
            "if (failing || !auto || !visible) return 'paused';", "return 'live';")),
    }
    for opener, (first, fragments) in want.items():
        body = _js_block(app, opener)
        if not body or not _js_first_after_brace(body, opener, first):
            return False
        if not all(f in body for f in fragments):
            return False
    markers = {"view_after": "viewAfter()", "back_label": "backLabelOf()",
               "default_build": "defaultBuildOf()", "running_strip": "runningStripOf()",
               "feed_state": "feedStateOf()"}
    return all("MIRROR: change together with " + js in py.get(name, "")
               for name, js in markers.items())


@_covers("view-state-is-the-designs", kind="behaviour",
         breaks=[lambda c: {"view_after": lambda nav, action, slug=None: dict(nav)},
                 lambda c: {"view_after": lambda nav, action, slug=None: dict(
                     view_after(nav, action, slug), came_from="home")},
                 lambda c: {"frame_inlined": dict(c["frame_inlined"],
                                                  views=c["frame_inlined"]["views"][:-1])},
                 lambda c: {"app_src": c["app_src"].replace(
                     "const next = viewAfter(this.nav, action, slug);",
                     "const next = this.nav;", 1)},
                 lambda c: {"page": c["page"].replace(":data-kw-view=", ":data-kw-mode=", 1)},
                 lambda c: {"back_label": lambda nav: BACK_HOME_LABEL}])
def _c_view_state(ctx):
    """The view state is the design's: the view is one of home, binders, waves,
    running, action or binder, with the open build, the open item and the view
    Back returns to. Opening a build remembers where it was opened from (unless
    from another build, which keeps the original); Back returns there, or to
    the summary from home, and words itself to match; the egg goes home and
    closes the open item; an unknown action changes nothing. Driven through the
    Python twin, and the page is held to the same table: it inlines the view
    list, starts on home, routes every move through viewAfter, says which view
    it is on, and draws Back on every view but home."""
    step, label, views = ctx["view_after"], ctx["back_label"], ctx["views"]
    if tuple(views) != ("home", "binders", "waves", "running", "action", "binder"):
        return False
    if list(views) != (ctx["frame_inlined"] or {}).get("views"):
        return False
    home = {"view": "home", "binder": None, "open_item": None, "came_from": "home"}
    opened = step(home, "open", "s-a")
    if opened != {"view": "binder", "binder": "s-a", "open_item": None, "came_from": "home"}:
        return False
    if step(opened, "back")["view"] != "home" or label(opened) != ctx["frame_words"]["back_home"]:
        return False
    waves = step(home, "waves")
    from_waves = step(waves, "open", "s-b")
    again = step(from_waves, "open", "s-c")
    if (from_waves["came_from"] != "waves" or again["came_from"] != "waves"
            or again["binder"] != "s-c" or label(again) != ctx["frame_words"]["back"]):
        return False
    if step(again, "back") != dict(again, view="waves"):
        return False
    if step(dict(again, open_item="s-c/x"), "home") != dict(again, view="home",
                                                            came_from="home", open_item=None):
        return False
    if step(waves, "no-such-view") != waves or step(waves, "binder") != waves:
        return False
    if label(waves) != ctx["frame_words"]["back_home"]:
        return False
    app, page = ctx["app_src"], ctx["page"]
    data = _js_block(app, "  data() {")
    if not all(f in data for f in ("view: 'home',", "binder: null,",
                                   "openItem: null,", "from: 'home',")):
        return False
    if "const next = viewAfter(this.nav, action, slug);" not in _js_block(app, "    go(action, slug, repo) {"):
        return False
    mains = _tags_with(page, "data-kw-main")
    backs = _tags_with(page, "data-kw-back")
    if len(mains) != 1 or _attrs(mains[0]).get(":data-kw-view") != "view":
        return False
    return (len(backs) == 1 and _attrs(backs[0]).get("v-if") == "!isHome"
            and _attrs(backs[0]).get("@click") == "go('back')"
            and _text_in(page, "data-kw-back") == "{{ backLabel }}")


@_covers("default-build-is-the-one-the-old-page-showed", kind="behaviour",
         breaks=[lambda c: {"default_build": lambda b: b[0]["slug"] if b else None},
                 lambda c: {"default_build": lambda b: next(
                     (x["slug"] for x in b if x.get("status") == "in_flight"), None)},
                 # the build panel back on the home view, beside the squares
                 lambda c: {"app_src": c["app_src"].replace(
                     "hostsPanel() { return this.view === 'binder'; },",
                     "hostsPanel() { return this.view === 'home' || this.view === 'binder'; },", 1)},
                 lambda c: {"app_src": c["app_src"].replace(
                     "return defaultBuildOf(this.allBinders);", "return null;", 1)}])
def _c_default_build(ctx):
    """The build view lives on the binder view only — the home view draws the
    four squares — and shows the build that was opened. When that build leaves
    the feed the view falls back to the build the old page showed by default:
    the build in flight; else the first not yet delivered, in the engine's
    order; else the first delivered, so a repo whose every build has shipped
    still shows one; nothing at all only for an empty feed."""
    show = ctx["default_build"]

    def row(slug, status):
        return {"slug": slug, "status": status}
    if show([]) is not None:
        return False
    if show([row("d", "merged"), row("n", "not_started"), row("f", "in_flight")]) != "f":
        return False
    if show([row("d", "merged"), row("n1", "not_started"), row("n2", "not_started")]) != "n1":
        return False
    if show([row("d1", "merged"), row("d2", "merged")]) != "d1":
        return False
    app = ctx["app_src"]
    hosts = _js_block(app, "    hostsPanel() {")
    slug = _js_block(app, "    shownSlug() {")
    shown = ctx["shown_accessor"]
    return ("return this.view === 'binder';" in hosts and "'home'" not in hosts
            and "this.allBinders.some(b => b.slug === open)" in slug
            and "return defaultBuildOf(this.allBinders);" in slug
            and "this.shownSlug" in shown
            and 'v-if="hostsPanel"' in ctx["page"])


@_covers("feed-dot-shows-three-states", kind="behaviour",
         breaks=[lambda c: {"feed_state": lambda s, f, a, v: "live"},
                 lambda c: {"feed_state": lambda s, f, a, v: "snapshot" if s else (
                     "paused" if f else "live")},
                 lambda c: {"feed_inlined": {k: v for k, v in c["feed_inlined"].items()
                                             if k != "snapshot"}},
                 lambda c: {"page": c["page"].replace(":data-kw-feed-state=", ":data-kw-feed-mode=", 1)},
                 lambda c: {"app_src": c["app_src"].replace("      this.tabVisible = visible;\n", "", 1)},
                 lambda c: {"css": c["css"].replace(
                     "background:var(--wait); animation:none;", "background:var(--wait);", 1)},
                 # the dot paused by the reader's own choice, titled as live
                 lambda c: {"app_src": c["app_src"].replace(
                     "return this.autoRefresh ? FEED.live : REFRESH.off;", "return FEED.live;", 1)}])
def _c_feed_three_states(ctx):
    """The live dot shows three readings: live, snapshot — a copy opened from a
    file, which never polls — and paused, when automatic refresh is off, the tab
    is hidden, or the feed has failed twice running. Driven through the Python
    twin over every combination. The page carries all three labels, binds the
    reading onto the dot's region and its title (which names a pause the reader
    chose as that choice, never as the feed failing), stills the dot in both of
    the other readings
    (the dot's own rule breathes, and reduced motion keeps it breathing), records the
    tab's visibility at each refresh step, and reads 'Updated <age>' beside it."""
    state = ctx["feed_state"]
    for snapshot in (True, False):
        for failing in (True, False):
            for auto in (True, False):
                for visible in (True, False):
                    got = state(snapshot, failing, auto, visible)
                    want = ("snapshot" if snapshot else
                            "paused" if (failing or not auto or not visible) else "live")
                    if got != want:
                        return False
    labels = ctx["feed_inlined"] or {}
    if set(labels) != {"live", "paused", "snapshot"} or len(set(labels.values())) != 3:
        return False
    page, app = ctx["page"], ctx["app_src"]
    feeds = _tags_with(page, "data-kw-feed")
    dots = _tags_with(page, "data-kw-feed-dot")
    if len(feeds) != 1 or len(dots) != 1 or dots[0] not in _subtree(page, feeds[0]):
        return False
    attrs = _attrs(feeds[0])
    if attrs.get(":data-kw-feed-state") != "feedState" or attrs.get(":title") != "feedLabel":
        return False
    css, breathe = ctx["css"], ctx["breathe_keyframe"]
    if not any(_animates_with(d, breathe) for d in _decls_for(css, ".hdr__dot")):
        return False
    for reading in ("paused", "snapshot"):
        if _resolved(_decls_for(css, ".hdr__feed--" + reading + " .hdr__dot"), "animation") != "none":
            return False
    if _class_binding(attrs) != {"hdr__feed--paused": "feedState === 'paused'",
                                 "hdr__feed--snapshot": "feedState === 'snapshot'"}:
        return False
    if "snapshot: location.protocol === 'file:'," not in _js_block(app, "  data() {"):
        return False
    if "this.tabVisible = visible;" not in _js_block(app, "    step(manual) {"):
        return False
    label = _js_block(app, "    feedLabel() {")
    if not all(f in label for f in ("return FEED.snapshot;", "return FEED.paused;",
                                    "return this.autoRefresh ? FEED.live : REFRESH.off;")):
        return False
    return "'Updated ' + ago" in _js_block(app, "    updatedLabel() {")


@_covers("unforced-page-follows-the-system-theme", kind="behaviour",
         breaks=[lambda c: {"render_themed": lambda s, t: c["render_themed"](s, t or "dark")},
                 lambda c: {"app_src": c["app_src"].replace(
                     "theme: window.__HATCH_THEME__ || storedTheme() || systemTheme(),",
                     "theme: storedTheme() || window.__HATCH_THEME__ || 'dark',", 1)},
                 lambda c: {"app_src": c["app_src"].replace(
                     "if (window.__HATCH_THEME__ || storedTheme()) document.documentElement",
                     "document.documentElement", 1)},
                 lambda c: {"render_hub_themed": lambda roster, t: c["render_hub_themed"](roster, t or "dark")},
                 lambda c: {"css": c["css"].replace("@media (prefers-color-scheme: light)", "@media (x-light)", 1)}])
def _c_unforced_follows_system(ctx):
    """With neither ?theme nor a stored choice the page follows the system.
    The precedence is ?theme, then the stored hatch-theme, then
    prefers-color-scheme, on a repo page and the hub home alike — the hub home
    is the same app document, so one rule serves both. An unforced document is
    served with no data-theme on its root and no forced theme for the app — so
    the sheet's prefers-color-scheme rule decides — while a forced one carries
    both. The app resolves the forced theme first, the stored one next and the
    system's last, and pins the root only when something chose a theme."""
    render, state = ctx["render_themed"], ctx["state"]
    for theme in (None, "light", "dark"):
        doc = render(state, theme)
        roots = _tags_named(doc, "html")
        if len(roots) != 1 or _attrs(roots[0]).get("data-theme") != theme:
            return False
        if "window.__HATCH_THEME__ = " + json.dumps(theme) + ";" not in doc:
            return False
    for theme in (None, "light", "dark"):
        doc = ctx["render_hub_themed"](ctx["hub_roster"], theme)
        roots = _tags_named(doc, "html")
        if len(roots) != 1 or _attrs(roots[0]).get("data-theme") != theme:
            return False
        if "window.__HATCH_THEME__ = " + json.dumps(theme) + ";" not in doc:
            return False
    if "@media (prefers-color-scheme: light)" not in ctx["css"]:
        return False
    app = ctx["app_src"]
    return ("theme: window.__HATCH_THEME__ || storedTheme() || systemTheme()," in app
            and "if (window.__HATCH_THEME__ || storedTheme()) document.documentElement" in app
            and "localStorage.getItem('hatch-theme')" in _js_block(app, "function storedTheme() {")
            and "prefers-color-scheme: light" in _js_block(app, "function systemTheme() {"))


@_covers("footer-reads-the-designs-two-lines", kind="rendered", hook="data-kw-footer",
         breaks=[lambda c: _renamed(c, "data-kw-footer", "page"),
                 lambda c: {"frame_words": dict(c["frame_words"], foot_credit="hatch · read-only")},
                 lambda c: _moved_inside(c, "data-kw-footer", "data-kw-main"),
                 lambda c: {"page": c["page"].replace(
                     html.escape(c["frame_words"]["foot_credit"]),
                     '<a href="https://example.invalid">'
                     + html.escape(c["frame_words"]["foot_credit"]) + "</a>", 1)}])
def _c_footer_two_lines(ctx):
    """The footer is the design's: two plain lines held apart — the tap hint and
    the configured release credit — as the frame's last child, below the view's
    column. Plain text: no link, no control, no heading. The credit is compared
    in its HTML-escaped form, so a branding value carrying markup is rendered as
    text and an unescaped or linked credit fails here rather than shipping."""
    page, words = ctx["page"], ctx["frame_words"]
    feet = _tags_with(page, "data-kw-footer")
    if len(feet) != 1 or _tag_name(feet[0]) != "footer":
        return False
    wraps = [t for t in _start_tags(page) if "wrap" in _attrs(t).get("class", "").split()]
    if len(wraps) != 1 or _child_tags(page, wraps[0])[-1:] != feet:
        return False
    kids = _child_tags(page, feet[0])
    if [_tag_name(k) for k in kids] != ["span", "span"]:
        return False
    block, texts, at = _subtree(page, feet[0]), [], len(feet[0])
    for kid in kids:
        start = block.index(kid, at) + len(kid)
        at = block.index(chr(60), start)
        texts.append(block[start:at])
    if texts != [html.escape(words["foot_hint"]), html.escape(words["foot_credit"])]:
        return False
    return (words["foot_credit"] == FOOT_CREDIT
            and words["foot_hint"] == FOOT_HINT)


@_covers("every-rendered-hook-is-covered", kind="behaviour",
         breaks=[lambda c: {"page": c["page"].replace(
             "data-kw-shell-repo", "data-kw-shell-repo data-kw-unread-probe", 1)}])
def _c_every_hook_covered(ctx):
    """Every data-kw hook the page actually renders is read by some registered
    check. A hook nobody reads is a test seam that looks like coverage and is
    not — and this fails in the item that added it, naming the hook, instead of
    surfacing much later as an unexplained sweep finding."""
    hooks = _rendered_hooks(ctx)
    return bool(hooks) and not [h for h in hooks if not _hook_is_read(h)]


# --- the home view: four squares and the headline ----------------------------
#
# The design's home (template L336-416): My builds, the waves in each build,
# what is running now and what needs you, under a header whose headline counts
# the healthy builds. The three models behind it are driven here through their
# Python twins over builds built for each check, since the pinned fixture holds
# one live build; the page's copies are held to the twins by
# home-mirrors-match-their-twins.

def _hb(slug: str, status: str, *statuses: str, title: str | None = None,
        deps: dict | None = None, **extra) -> dict:
    """One build for the home checks: its status, one item per entry in
    `statuses` (ids <slug>-0, <slug>-1, …), the per-state counts the engine
    would carry for them, and any extra row fields (superseded_by, archived).
    `deps` maps an item's index to the indexes it depends on."""
    ids = ["%s-%d" % (slug, i) for i in range(len(statuses))]
    detail = [{"id": ids[i], "title": "item %d of %s" % (i, slug), "status": st,
               "deps": [ids[d] for d in (deps or {}).get(i, [])]}
              for i, st in enumerate(statuses)]
    counts = {k: sum(1 for st in statuses if st == k) for k in _ENGINE_ITEM_STATES}
    return dict({"slug": slug, "title": title, "status": status,
                 "items": dict(counts, total=len(statuses), detail=detail)}, **extra)


def _home_repo(binders: list, level: str = "item", name: str = "r") -> dict:
    """One repo for the home checks: its builds and a next action at `level`."""
    return {"name": name, "state": {"binders": binders,
                                    "next_action": {"level": level, "human": "do " + level}}}


@_covers("home-is-four-squares", kind="behaviour",
         breaks=[lambda c: _renamed(c, "data-kw-home", "page"),
                 lambda c: {"page": c["page"].replace('data-kw-square="needs"',
                                                      'data-kw-square="action"', 1)},
                 lambda c: {"page": c["page"].replace('v-for="b in homeBuilds"',
                                                      'v-for="b in homeBuilds.slice(1)"', 1)},
                 lambda c: _moved_inside(c, "data-kw-build-view", "data-kw-home"),
                 lambda c: {"home_builds": lambda r: [x for x in c["home_builds"](r)
                                                      if x["roll"] != "delivered"]},
                 lambda c: {"app_src": c["app_src"].replace(
                     "homeBuilds() { return homeBuildsOf(this.repos); },",
                     "homeBuilds() { return homeBuildsOf([]); },", 1)}])
def _c_home_is_four_squares(ctx):
    """The home view is the design's four squares — My builds, Waves in each
    build, Running now, Needs you, in that order — and nothing else: one grid,
    shown on home and only there, inside the main column, its four direct
    children the four squares, each titled in the design's words. With the rail
    gone, My builds is the one place that lists every build: its rows run over
    every build in the page's repos, one row each and every one opening its
    binder view. The build view the home view once hosted lives on the
    binder view only, so it is not inside the grid."""
    page, words = ctx["page"], ctx["home_words"]
    homes = _tags_with(page, "data-kw-home")
    mains = _tags_with(page, "data-kw-main")
    if len(homes) != 1 or len(mains) != 1 or _tag_name(homes[0]) != "div":
        return False
    if _attrs(homes[0]).get("v-if") != "isHome" or homes[0] not in _subtree(page, mains[0]):
        return False
    grid = _subtree(page, homes[0])
    squares = _child_tags(page, homes[0])
    if [_attrs(t).get("data-kw-square") for t in squares] != list(words["squares"]):
        return False
    for tag in squares:
        if words["titles"][_attrs(tag)["data-kw-square"]] not in _subtree(page, tag):
            return False
    rows = _tags_with(page, "data-kw-home-build")
    if len(rows) != 1 or rows[0] not in _subtree(page, squares[0]):
        return False
    row = _attrs(rows[0])
    if row.get("v-for") != "b in homeBuilds" or row.get("@click") != "go('open', b.slug, b.repo)":
        return False
    panels = _tags_with(page, "data-kw-build-view")
    if len(panels) != 1 or panels[0] in grid:
        return False
    app = ctx["app_src"]
    if ("homeBuilds() { return homeBuildsOf(this.repos); }," not in app
            or "repos() { return reposOf(this.feeds); }," not in app):
        return False
    builds = [_hb("a", "in_flight", "building"), _hb("b", "merged", "done"),
              _hb("c", "not_started", "ready"), _hb("d", "merged", "done", archived=True),
              _hb("e", "in_flight", "failed", superseded_by="f")]
    listed = [r["slug"] for r in ctx["home_builds"]([_home_repo(builds)])]
    return sorted(listed) == sorted(b["slug"] for b in builds)


@_covers("home-grid-fits-the-viewport-and-folds", kind="behaviour",
         breaks=[lambda c: {"css": _restyled(c["css"], ".four",
                                             "grid-template-columns:minmax(0,1fr)")},
                 lambda c: {"css": c["css"].replace(
                     "height:calc(100vh - 24px)", "min-height:calc(100vh - 24px)", 1)},
                 lambda c: {"css": _restyled(c["css"], ".sq__list", "overflow-y:visible")},
                 lambda c: {"css": _restyled(c["css"], ".sq", "min-height:auto")},
                 lambda c: {"css": c["css"].replace("@media (max-width:760px)",
                                                    "@media (max-width:560px)", 1)},
                 lambda c: {"page": c["page"].replace("'wrap--fit': isHome",
                                                      "'wrap--fit': false", 1)}])
def _c_home_grid_fits_and_folds(ctx):
    """At 1280x900 the grid fits the viewport and each square's list scrolls
    inside it: on home the frame IS the viewport's height less the body's
    padding (not a minimum it can grow past), the main column and the grid take
    what is left without a floor of their own, a square cannot grow past its
    row, and its list is the part that scrolls. The grid is two by two, and
    below 760px it becomes one column and the frame gives its fixed height
    back. That it actually paints that way is a browser result, walked as
    home-grid-fits-a-1280x900-viewport; this holds the rules that produce it."""
    css = ctx["css"]
    wraps = [t for t in _start_tags(ctx["page"])
             if "wrap" in _attrs(t).get("class", "").split()]
    if len(wraps) != 1 or _class_binding(_attrs(wraps[0])).get("wrap--fit") != "isHome":
        return False
    fit = _decls_for(css, ".wrap--fit")
    if _resolved(fit, "height") != "calc(100vh - 24px)" or _resolved(fit, "min-height"):
        return False
    main = _decls_for(css, ".wrap--fit .main")
    if _resolved(main, "flex") != "1" or _resolved(main, "min-height") != "0":
        return False
    four = _decls_for(css, ".four")
    if (_resolved(four, "display") != "grid"
            or _resolved(four, "grid-template-columns") != "repeat(2,minmax(0,1fr))"
            or _resolved(four, "grid-template-rows") != "repeat(2,minmax(0,1fr))"
            or _resolved(four, "min-height") != "0"):
        return False
    square = _decls_for(css, ".sq")
    if _resolved(square, "min-height") != "0" or _resolved(square, "overflow") != "hidden":
        return False
    lists = _decls_for(css, ".sq__list")
    if (_resolved(lists, "overflow-y") != "auto" or _resolved(lists, "flex") != "1"
            or _resolved(lists, "min-height") != "0"):
        return False
    narrow = _at_rule_body(css, "max-width:760px")
    return (_resolved(_decls_for(narrow, ".four"), "grid-template-columns") == "minmax(0,1fr)"
            and _resolved(_decls_for(narrow, ".wrap--fit"), "height") == "auto")


@_covers("build-roll-precedence", kind="behaviour",
         breaks=[lambda c: {"build_roll": lambda b: (
                     "halted" if b.get("status") == "in_flight" and _failed_items(b)
                     else c["build_roll"](b))},
                 lambda c: {"build_roll": lambda b: (
                     "ready" if b.get("status") == "in_flight"
                     and not _failed_items(b) and not (b["items"]["building"] or b["items"]["ready"]
                                                       or b["items"]["blocked"])
                     else c["build_roll"](b))},
                 lambda c: {"build_roll": lambda b: c["build_roll"](dict(b, archived=False))}])
def _c_build_roll_precedence(ctx):
    """buildRollOf() puts every build in exactly one roll, by precedence:
    replaced (superseded_by set) before anything else, then delivered (merged
    or archived), halted (in flight with a failed item), ready for your OK (in
    flight, at least one item, every item done or accepted — the engine's
    landing condition), running (any other build in flight) and waiting (not
    started). Driven through the twin over a build in each roll and over the
    boundaries between them: a replaced build that is also merged, in flight
    and failed, or landing-ready; a ready build whose items were accepted; a
    build whose items are built but not merged, which is running, not ready;
    and a build in flight with no items, which is running."""
    roll = ctx["build_roll"]
    cases = [
        (_hb("a", "merged", "done", superseded_by="z"), "replaced"),
        (_hb("b", "in_flight", "failed", "done", superseded_by="z"), "replaced"),
        (_hb("c", "in_flight", "done", "accepted", superseded_by="z"), "replaced"),
        (_hb("d", "merged", "done"), "delivered"),
        (_hb("e", "not_started", "done", archived=True), "delivered"),
        (_hb("f", "in_flight", "failed", "done"), "halted"),
        (_hb("g", "in_flight", "failed", "building"), "halted"),
        (_hb("h", "in_flight", "done", "accepted"), "ready"),
        (_hb("i", "in_flight", "done", "built"), "running"),
        (_hb("j", "in_flight", "building", "ready"), "running"),
        (_hb("k", "in_flight"), "running"),
        (_hb("l", "not_started", "ready", "blocked"), "waiting"),
    ]
    if not all(roll(b) == want for b, want in cases):
        return False
    return set(ctx["home_tables"]["rolls"]) == {want for _b, want in cases}


@_covers("delivered-builds-sort-last", kind="behaviour",
         breaks=[lambda c: {"home_builds": lambda r: list(reversed(c["home_builds"](r)))},
                 lambda c: {"home_builds": lambda r: sorted(
                     c["home_builds"](r), key=lambda x: x["roll"] != "delivered")},
                 lambda c: {"home_inlined": dict(c["home_inlined"], roll_order=list(
                     reversed(c["home_inlined"]["roll_order"])))},
                 # the rolls in order, but the engine's order lost inside them
                 lambda c: {"home_builds": lambda r: sorted(
                     c["home_builds"](r), key=lambda x: (HOME_ROLL_ORDER.index(x["roll"]),
                                                         x["slug"]))}])
def _c_delivered_builds_sort_last(ctx):
    """My builds reads halted, ready for your OK, running, waiting, replaced,
    delivered — so a delivered build always sorts below every live one and the
    finished history never pushes live work out of the square. Within a roll
    the engine's own order holds (the sort is stable, on both sides). Driven
    through the twin over builds handed over in an order that is neither, and
    the page sorts by the same table the server inlines."""
    order = ("halted", "ready", "running", "waiting", "replaced", "delivered")
    if tuple(ctx["home_tables"]["roll_order"]) != order:
        return False
    if (ctx["home_inlined"] or {}).get("roll_order") != list(order):
        return False
    builds = [_hb("d2", "merged", "done"), _hb("w2", "not_started", "ready"),
              _hb("r1", "in_flight", "building"), _hb("d1", "merged", "done", archived=True),
              _hb("x1", "in_flight", "done", superseded_by="r1"),
              _hb("h1", "in_flight", "failed"), _hb("w1", "not_started", "ready"),
              _hb("k1", "in_flight", "done", "accepted")]
    rows = ctx["home_builds"]([_home_repo(builds)])
    if [r["slug"] for r in rows] != ["h1", "k1", "r1", "w2", "w1", "x1", "d2", "d1"]:
        return False
    return "HOME.roll_order.indexOf(x.roll)" in _js_block(ctx["app_src"], "function homeBuildsOf(repos) {")


@_covers("my-builds-row-shows-state-title-progress-and-word", kind="behaviour",
         breaks=[lambda c: _renamed(c, "data-kw-home-roll", "page"),
                 lambda c: {"home_builds": lambda r: [dict(x, name=_title_case(x["slug"]))
                                                      for x in c["home_builds"](r)]},
                 lambda c: {"home_builds": lambda r: [dict(x, pct_label="25%")
                                                      for x in c["home_builds"](r)]},
                 lambda c: {"page": c["page"].replace("{{ b.pct_label }}", "", 1)},
                 lambda c: {"home_tables": dict(c["home_tables"], rolls=dict(
                     c["home_tables"]["rolls"], ready=dict(c["home_tables"]["rolls"]["ready"],
                                                           word="Running")))}])
def _c_my_builds_row(ctx):
    """Every My builds row carries the build's state dot, its title — its slug
    when the title is null, never a title-cased guess — a progress bar, the
    percent complete (done plus accepted over total, so a waiver counts as
    merged) and the short state word, each drawn from the row's own fields.
    The six rolls each have their own word, and the two that wait on a person
    carry the HAT chip."""
    rows = ctx["home_builds"]([_home_repo([
        _hb("plain-slug", "in_flight", "done", "accepted", "building", "ready"),
        _hb("named", "in_flight", "done", "accepted", title="A named build")])])
    by_slug = {r["slug"]: r for r in rows}
    first, second = by_slug["plain-slug"], by_slug["named"]
    if first["name"] != "plain-slug" or second["name"] != "A named build":
        return False
    if first["pct_label"] != "50%" or second["pct_label"] != "100%":
        return False
    rolls = ctx["home_tables"]["rolls"]
    if len({m["word"] for m in rolls.values()}) != len(rolls):
        return False
    if first["word"] != rolls["running"]["word"] or second["word"] != rolls["ready"]["word"]:
        return False
    if not second["hat"] or first["hat"]:
        return False
    page = ctx["page"]
    tags = _tags_with(page, "data-kw-home-build")
    if len(tags) != 1 or _attrs(tags[0]).get(":data-kw-home-roll") != "b.roll":
        return False
    block = _subtree(page, tags[0])
    shown = all("{{ " + field + " }}" in block for field in ("b.name", "b.pct_label", "b.word"))
    return shown and all(field in block for field in ("b.color", "b.hat", "b.ink"))


@_covers("headline-counts-healthy-builds-and-who-needs-you", kind="behaviour",
         breaks=[lambda c: _renamed(c, "data-kw-headline", "page"),
                 lambda c: {"app_src": c["app_src"].replace(
                     "headline() { return headlineOf(this.repos); },",
                     "headline() { return ''; },", 1)},
                 # archived builds counted as live
                 lambda c: {"home_headline": lambda r: HEADLINE_FMT.format(
                     n=sum(1 for x in r[0]["state"]["binders"]
                           if not x.get("superseded_by") and not _failed_items(x)),
                     m=sum(1 for x in r[0]["state"]["binders"] if not x.get("superseded_by")),
                     k=len(needs_you(r)))},
                 # K counting the halted items alone
                 lambda c: {"home_headline": lambda r: c["home_headline"](r).rpartition(
                     "·")[0] + "· %d need you" % sum(len(_failed_items(x))
                                                     for x in r[0]["state"]["binders"])},
                 lambda c: {"home_tables": dict(c["home_tables"],
                                                headline_fmt="{n}/{m} healthy, {k} waiting")}])
def _c_headline(ctx):
    """The header's headline slot reads 'N of M builds healthy · K need you':
    M the live builds (not archived, not replaced), N those with no failed
    item, K the needs-you rows. Driven through the twin over states where each
    number changes on its own — an item failing in a landing-ready build trades
    its ready row for a halted one, so only N moves; that plus a new queued
    build moves only M; a build reaching the landing condition moves only K —
    and the slot sits in the header and renders the page's headlineOf()."""
    say = ctx["home_headline"]
    if ctx["home_tables"]["headline_fmt"] != "{n} of {m} builds healthy · {k} need you":
        return False
    shipped = _hb("old", "merged", "done", archived=True)
    base = [shipped, _hb("land", "in_flight", "done", "done"),
            _hb("run", "in_flight", "done", "building")]
    only_n = [shipped, _hb("land", "in_flight", "done", "failed"),
              _hb("run", "in_flight", "done", "building")]
    only_m = only_n + [_hb("queued", "not_started", "ready")]
    only_k = [shipped, _hb("land", "in_flight", "done", "done"),
              _hb("run", "in_flight", "done", "done")]
    readings = [say([_home_repo(b)]) for b in (base, only_n, only_m, only_k)]
    if readings != ["2 of 2 builds healthy · 1 need you",
                    "1 of 2 builds healthy · 1 need you",
                    "2 of 3 builds healthy · 1 need you",
                    "2 of 2 builds healthy · 2 need you"]:
        return False
    page = ctx["page"]
    slots = _tags_with(page, "data-kw-headline")
    heads = _tags_with(page, "data-kw-header")
    if len(slots) != 1 or len(heads) != 1 or slots[0] not in _subtree(page, heads[0]):
        return False
    if _text_in(page, "data-kw-headline") != "{{ headline }}":
        return False
    return ("headline() { return headlineOf(this.repos); }," in ctx["app_src"]
            and (ctx["home_inlined"] or {}).get("headline_fmt")
            == ctx["home_tables"]["headline_fmt"])


@_covers("replaced-builds-need-no-one", kind="behaviour",
         breaks=[lambda c: {"needs_you": lambda r: needs_you([dict(x, state=dict(
                     x["state"], binders=[dict(b, superseded_by=None)
                                          for b in x["state"]["binders"]])) for x in r])},
                 lambda c: {"build_roll": lambda b: c["build_roll"](dict(b, superseded_by=None))},
                 lambda c: {"home_headline": lambda r: home_headline([dict(x, state=dict(
                     x["state"], binders=[dict(b, superseded_by=None)
                                          for b in x["state"]["binders"]])) for x in r])}])
def _c_replaced_builds_need_no_one(ctx):
    """A replaced build's remaining work is its successor's, so nothing about it
    waits on a person. A superseded in-flight build with a failed item and one
    with every item done both roll 'replaced', add no needs-you row, and leave
    the headline — K, and M with it — exactly where it was without them."""
    halted = _hb("old-a", "in_flight", "done", "failed", superseded_by="new")
    landed = _hb("old-b", "in_flight", "done", "accepted", superseded_by="new")
    live = [_hb("new", "in_flight", "done", "building")]
    with_them = [_home_repo(live + [halted, landed])]
    without = [_home_repo(live)]
    return (ctx["build_roll"](halted) == "replaced" and ctx["build_roll"](landed) == "replaced"
            and ctx["needs_you"](with_them) == ctx["needs_you"](without) == []
            and ctx["home_headline"](with_them) == ctx["home_headline"](without)
            == "1 of 1 builds healthy · 0 need you")


@_covers("needs-you-rows-are-the-engines", kind="behaviour",
         breaks=[lambda c: {"needs_you": lambda r: [x for x in c["needs_you"](r)
                                                    if x["kind"] != "ready"]},
                 lambda c: {"needs_you": lambda r: c["needs_you"](r) + [
                     {"kind": "item", "tag": "", "repo": "", "slug": None, "line": ""}
                     for x in r if x["state"]["next_action"]["level"] == "item"]},
                 lambda c: {"needs_you": lambda r: [x for x in c["needs_you"](r)
                                                    if x["slug"] is not None]},
                 # one row per halted BUILD instead of one per failed item
                 lambda c: {"needs_you": lambda r: list({(x["kind"], x["slug"]): x
                                                         for x in c["needs_you"](r)}.values())},
                 lambda c: {"home_inlined": dict(c["home_inlined"], level_tags={})}])
def _c_needs_you_rows(ctx):
    """needsYouOf() returns one row per failed item and one per landing-ready
    build (in flight, at least one item, every item done or accepted), both
    only for builds no successor replaced, plus one row per repo whose next
    action's level is error, repair, review or blocked — and nothing else: a
    running build, a queued one, a delivered one and a repo whose next action
    an agent runs add none. The landing condition is read against the engine
    itself: for a repo whose only build is landing-ready, the engine's own next
    action is the landing, and the twin has that build's ready row."""
    rows = ctx["needs_you"]
    two_failed = _hb("h", "in_flight", "failed", "failed", "done")
    landing = _hb("l", "in_flight", "done", "accepted")
    quiet = [_hb("r", "in_flight", "building"), _hb("q", "not_started", "ready"),
             _hb("d", "merged", "done"), _hb("b", "in_flight", "done", "built")]
    got = rows([_home_repo([two_failed, landing] + quiet)])
    if [(r["kind"], r["slug"]) for r in got] != [("halted", "h"), ("halted", "h"), ("ready", "l")]:
        return False
    for level in ("error", "repair", "review", "blocked"):
        one = rows([_home_repo(quiet, level=level)])
        if [(r["kind"], r["slug"]) for r in one] != [(level, None)]:
            return False
    for level in ("item", "landing", "binder", "done", "empty", "cleanup"):
        if rows([_home_repo(quiet, level=level)]):
            return False
    both = rows([_home_repo(quiet, name="a"), _home_repo([landing], level="review", name="b")])
    if [(r["repo"], r["kind"], r["slug"]) for r in both] != [("b", "review", None),
                                                             ("b", "ready", "l")]:
        return False
    engine = hatch_next._next_action([dict(landing, after=[])], ["l"], [], [])
    if engine.get("level") != "landing":
        return False
    inlined = (ctx["home_inlined"] or {}).get("level_tags") or {}
    return set(inlined) == {"error", "repair", "review", "blocked"}


@_covers("waves-square-numbers-each-wave", kind="behaviour",
         breaks=[lambda c: _renamed(c, "data-kw-home-wave", "page"),
                 lambda c: {"wave_chips": lambda b: [dict(x, label="W%d" % (x["n"] - 1))
                                                     for x in c["wave_chips"](b)]},
                 lambda c: {"wave_chips": lambda b: [dict(x, state="waiting")
                                                     for x in c["wave_chips"](b)]},
                 lambda c: {"page": c["page"].replace(':data-kw-wave-state="s.state" v-for="(s, si) in b.steps"',
                                                      ':data-kw-wave-state="b.roll" v-for="(s, si) in b.steps"', 1)},
                 # the boxes drawn without their lane's frame
                 lambda c: {"page": c["page"].replace(
                     '<span class="wbox wbox--sq" :class="\'wbox--\' + s.lane"', '<span class="wbox wbox--sq"', 1)}])
def _c_waves_square(ctx):
    """Waves in each build shows every build's waves as numbered chips, W1..Wn
    by dependency depth — the same grouping the strip and the panel use — each
    in the state of what it holds: halted, running, done or waiting. The chips
    sit in the waves square, one per wave of each build row, each inside a box
    in its wave's lane (`'wbox--' + s.lane`, the frame the square's legend keys),
    iterated over the row's wave_steps() boxes."""
    chips = ctx["wave_chips"]
    build = _hb("w", "in_flight", "done", "accepted", "building", "failed", "ready", "blocked",
                deps={2: [0], 3: [0], 4: [2], 5: [4]})
    got = [(c["label"], c["state"]) for c in chips(build)]
    if got != [("W1", "done"), ("W2", "halted"), ("W3", "waiting"), ("W4", "waiting")]:
        return False
    if [(c["label"], c["state"]) for c in chips(_hb("r", "in_flight", "building"))] != [("W1", "running")]:
        return False
    page = ctx["page"]
    squares = [t for t in _tags_with(page, "data-kw-square")
               if _attrs(t).get("data-kw-square") == "waves"]
    tags = _tags_with(page, "data-kw-home-wave")
    if len(squares) != 1 or len(tags) != 1 or tags[0] not in _subtree(page, squares[0]):
        return False
    attrs = _attrs(tags[0])
    return (attrs.get("v-for") == "(s, si) in b.steps"
            and attrs.get(":data-kw-wave-state") == "s.state"
            and ":class=\"'wbox--' + s.lane\"" in _subtree(page, tags[0]))


