@_covers("retired-tokens-unreferenced", kind="behaviour",
         breaks=[lambda c: {"state_meta": dict(
             c["state_meta"],
             blocked=dict(c["state_meta"]["blocked"], color="var(--live)"))},
                 lambda c: {"css": c["css"].replace("var(--surface-2)",
                                                    "var(--chip)")},
                 lambda c: {"retired": dict(c["retired"], **{"--tree": "--gone"})}])
def _c_retired_tokens_unreferenced(ctx):
    """Reverse direction, and it is the one that matters. A forward-only "every
    referenced variable is defined" check passes happily while a metadata entry
    still names --tree, because --tree is simply gone from both sides. So: each
    retired name is referenced nowhere, and each has a destination that IS
    defined — a rename with a recorded landing place, not a deletion."""
    defined = set(_VAR_DEF_RE.findall(ctx["css"]))
    surfaces = (ctx["css"] + ctx["app_src"]
                + json.dumps(ctx["state_meta"]) + json.dumps(ctx["phase_meta"])
                + json.dumps(ctx["repo_chip"]) + json.dumps(ctx["icons"]))
    for old, new in ctx["retired"].items():
        if re.search(r"(?<![\w-])" + re.escape(old) + r"(?![\w-])", surfaces):
            return False
        if new not in defined:
            return False
    return bool(ctx["retired"])


def _hex_rgb(value: str) -> tuple[int, int, int] | None:
    """A #RRGGBB palette value as three 0..255 channels, or None for anything
    else — an rgba(), a named colour, a short hex — so a rule stated over hex
    values cannot be satisfied by a value it cannot read."""
    m = re.fullmatch(r"#([0-9A-Fa-f]{6})", value.strip())
    return tuple(int(m.group(1)[i:i + 2], 16) for i in (0, 2, 4)) if m else None


def _contrast(a: tuple[int, int, int], b: tuple[int, int, int]) -> float:
    """The WCAG 2 contrast ratio between two sRGB colours."""
    def lum(rgb):
        lin = [c / 12.92 if c <= 0.04045 else ((c + 0.055) / 1.055) ** 2.4
               for c in (x / 255 for x in rgb)]
        return 0.2126 * lin[0] + 0.7152 * lin[1] + 0.0722 * lin[2]
    hi, lo = sorted((lum(a), lum(b)), reverse=True)
    return (hi + 0.05) / (lo + 0.05)


def _over(fg: tuple[int, int, int], share: float,
          ground: tuple[int, int, int]) -> tuple[int, int, int]:
    """`fg` laid over `ground` at `share` opacity, rounded per channel."""
    return tuple(round(share * f + (1 - share) * g) for f, g in zip(fg, ground))


# --- the contrast floor: which text sits on which ground ----------------------
#
# The dark rule above holds each lifted role to the floor on the grounds the plan
# named. The page paints more pairings than that, and only the page knows which:
# a muted meta line inside an item card sits on the card's state tint, a link in
# a hover row on --surface-2. So the pairs are DERIVED — the stylesheet's cascade
# walked over the page's own templates — and _CONTRAST_PAIRS is required to
# equal what the walk finds, so a stylesheet change that paints a new pairing
# fails until the pair is added to the table and clears the floor.

_CONTRAST_COLOUR_PROPS = ("color", "background", "background-color")
# A compound selector the walk can read: an optional element name, classes, and
# pseudo-classes or pseudo-elements. Anything else in a colour-bearing rule — a
# child or sibling combinator, an attribute selector, :not() — is refused.
_CONTRAST_COMPOUND_RE = re.compile(r"([a-z][\w-]*)?((?:\.[\w-]+)*)((?::{1,2}[\w-]+)*)")
_CONTRAST_PSEUDO_ELEMENTS = ("::before", "::after")


def _contrast_name(value: str) -> str:
    """A colour value as the pair table spells it: `var(--x)` as `--x`, anything
    else (a hex, an rgba(), a color-mix()) as written."""
    m = re.fullmatch(r"var\(\s*(--[\w-]+)\s*\)", value.strip())
    return m.group(1) if m else value.strip()


def _contrast_rules(css: str) -> list[dict]:
    """Every rule in `css` that declares a text colour or a ground, one entry per
    selector of a grouped rule, with its specificity and source order. Rules in
    a conditional at-rule (@media, @supports) are read as if they applied, the
    conservative direction for a floor; @keyframes and @font-face carry no text
    colour and are skipped. Raises ValueError on a selector or an !important
    colour the walk cannot place, so a sheet it cannot read fails the check."""
    out: list[dict] = []

    def walk(text: str) -> None:
        for prelude, body in _css_sections(text):
            if prelude.startswith("@"):
                if not prelude.startswith(("@keyframes", "@font-face")):
                    walk(body)
                continue
            decls = {}
            for decl in body.split(";"):
                prop, sep, value = decl.partition(":")
                if sep and prop.strip() in _CONTRAST_COLOUR_PROPS:
                    if "!important" in value:
                        raise ValueError("!important colour in " + prelude)
                    decls[prop.strip()] = value.strip()
            if not decls:
                continue
            for sel in prelude.split(","):
                comps = []
                for part in sel.split():
                    m = _CONTRAST_COMPOUND_RE.fullmatch(part)
                    if not m:
                        raise ValueError("unreadable selector " + sel.strip())
                    pseudos = re.findall(r"::?[\w-]+", m.group(3))
                    comps.append((m.group(1) or "",
                                  frozenset(c for c in m.group(2).split(".") if c),
                                  tuple(pseudos)))
                pseudo_classes = sum(1 for _, _, ps in comps for p in ps
                                     if not p.startswith("::"))
                elements = (sum(1 for t, _, _ in comps if t)
                            + sum(1 for _, _, ps in comps for p in ps
                                  if p.startswith("::")))
                out.append({"comps": comps, "decls": decls, "order": len(out),
                            "spec": (sum(len(c) for _, c, _ in comps)
                                     + pseudo_classes, elements),
                            "stateful": pseudo_classes > 0})
    walk(css)
    return out


def _contrast_templates(app_src: str) -> tuple[str, dict[str, str]]:
    """The page's root template and each component's, keyed by the tag the root
    template mounts it with (`CopyRun` is `<copy-run>`). A component whose
    template is a named constant (`template: REVIEW_STRIP_TEMPLATE`) is read
    through that constant."""
    comps: dict[str, str] = {}
    for m in re.finditer(r"const ([A-Z]\w*) = \{(.*?)\n\};", app_src, re.S):
        body = m.group(2)
        lit = re.search(r"template: `(.*?)`", body, re.S)
        if lit:
            src = lit.group(1)
        else:
            named = re.search(r"template: ([A-Z_]+)", body)
            const = named and re.search(r"const " + named.group(1) + r" = `(.*?)`;",
                                        app_src, re.S)
            if not const:
                continue
            src = const.group(1)
        comps[re.sub(r"(?<!^)([A-Z])", r"-\1", m.group(1)).lower()] = src
    i = app_src.rindex("  template: `") + len("  template: `")
    return app_src[i:app_src.index("`", i)], comps


def _contrast_tree(src: str) -> dict:
    """A template as an element tree: each node its tag, attributes, children,
    and whether it carries text of its own (literal text or an interpolation).
    Void elements and Vue's <template> open no level — a <template v-for> is a
    loop, so its children belong to its parent."""
    from html.parser import HTMLParser

    class _Tree(HTMLParser):
        def __init__(self):
            super().__init__(convert_charrefs=True)
            self.root = {"tag": "", "attrs": {}, "kids": [], "text": False}
            self.stack = [self.root]

        def handle_starttag(self, tag, attrs):
            node = {"tag": tag, "attrs": {k: v or "" for k, v in attrs},
                    "kids": [], "text": False}
            self.stack[-1]["kids"].append(node)
            if tag not in _NON_NESTING:
                self.stack.append(node)

        def handle_startendtag(self, tag, attrs):
            self.stack[-1]["kids"].append(
                {"tag": tag, "attrs": {k: v or "" for k, v in attrs},
                 "kids": [], "text": False})

        def handle_endtag(self, tag):
            for i in range(len(self.stack) - 1, 0, -1):
                if self.stack[i]["tag"] == tag:
                    del self.stack[i:]
                    return

        def handle_data(self, data):
            if data.strip():
                self.stack[-1]["text"] = True

    parser = _Tree()
    parser.feed(src)
    parser.close()
    return parser.root


def _contrast_bound(node: dict, prop: str) -> str | None:
    """The expression a `:style` binding gives `prop`, or None when unbound."""
    m = re.search(r"(?<![\w-])" + prop + r"\s*:\s*([^,}]+)", node["attrs"].get(":style", ""))
    return m.group(1).strip() if m else None


def _contrast_pairs_derived(css: str, app_src: str,
                            tables: dict[str, dict]) -> set[tuple[str, tuple[str, ...]]]:
    """Every (text colour, ground) pairing the page paints, from its stylesheet
    walked over its templates. A ground is a tuple of layers, topmost first,
    ending at the first opaque one, so an alpha ground carries the ground it is
    composited over.

    What the walk reads, and every place it stops:
      - TEXT is an element with text of its own in the template, or a
        ::before/::after rule that declares a colour. An icon is a glyph, not
        text, and is not read.
      - Its COLOUR is the winning `color` of the rules that match it, by
        specificity then source order; `inherit`, `currentColor` and no rule at
        all take the parent's. An <a> or <button> carrying text with no colour
        rule raises, because the browser gives those its own colour rather than
        the parent's. A colour bound inline (`:style` color) is followed only
        when the binding reads a row of one of `tables` (`it.color` is a row of
        the state table, `w.step.color` of the wave lanes); any other bound
        colour is not a stylesheet rule's colour, so it and the descendants that
        inherit it are not read.
      - Its GROUND is its own winning background, else the parent's.
        `transparent`, `none` and an empty binding let the parent's show
        through; an rgba() or color-mix() with transparent is laid over it. A
        ground bound inline is resolved through `tables` and raises when the
        binding names no table and stylesheet text sits on it — an unread ground
        under stylesheet text would be a hole in the floor (a bound ground with
        only bound-colour text on it, a state pill, is not read). A <button> with no background rule raises for the
        same reason as its colour.
      - VARIANTS: each element is read with its static classes, then with each
        `:class` literal added one at a time (a literal ending in '-' expands
        to every stylesheet class it prefixes), each with and without the
        pseudo-classes (:hover and the like) a matching rule names. Bindings
        that read the same row (`it.tint` and `it.color`) take that row
        together, never one row's tint under another's colour.
      - Components are walked where their tag appears, inside the ancestors of
        that tag. Selectors with a combinator other than descendant, or an
        attribute or :not() part, raise rather than being skipped."""
    rules = _contrast_rules(css)
    stylesheet_classes = set(re.findall(r"\.([\w-]+)", css))
    root_src, comp_srcs = _contrast_templates(app_src)
    comps = {name: _contrast_tree(src) for name, src in comp_srcs.items()}
    raw: set[tuple[str, tuple[str, ...]]] = set()

    def compound_ok(comp, tag, classes, stateful, pseudo):
        t, cls, ps = comp
        if (t and t != tag) or not cls <= classes:
            return False
        if any(p.startswith("::") for p in ps) != bool(pseudo):
            return False
        return all(p == pseudo if p.startswith("::") else stateful for p in ps)

    def rule_matches(rule, tag, classes, stateful, ancestors, pseudo=None):
        comps_ = rule["comps"]
        if not compound_ok(comps_[-1], tag, classes, stateful, pseudo):
            return False
        i = len(ancestors) - 1
        for comp in reversed(comps_[:-1]):
            while i >= 0 and not compound_ok(comp, *ancestors[i], None):
                i -= 1
            if i < 0:
                return False
            i -= 1
        return True

    def winner(matched, props):
        hits = [r for r in matched if any(p in r["decls"] for p in props)]
        if not hits:
            return None
        best = max(hits, key=lambda r: (r["spec"], r["order"]))
        return next(best["decls"][p] for p in props if p in best["decls"])

    def ground_of(value, below):
        v = value.strip()
        if v in ("transparent", "none", ""):
            return below
        if v.startswith(("rgba(", "color-mix(")):
            return (_contrast_name(v),) + below
        return (_contrast_name(v),)

    def bound_ref(expr):
        head, _, field = expr.rpartition(".")
        if head not in tables:
            return None
        return "@" + head + "." + field

    def visit(node, ancestors, colour, ground):
        if node["tag"] in comps:
            for kid in comps[node["tag"]]["kids"]:
                visit(kid, ancestors, colour, ground)
            return
        if not node["tag"]:
            for kid in node["kids"]:
                visit(kid, ancestors, colour, ground)
            return
        tag, attrs = node["tag"], node["attrs"]
        base = frozenset(attrs.get("class", "").split())
        optional = set()
        for lit in re.findall(r"'([\w-]+)'", attrs.get(":class", "")):
            optional |= ({c for c in stylesheet_classes if c.startswith(lit)}
                         if lit.endswith("-") else {lit})
        for classes in [base] + [base | {o} for o in sorted(optional)]:
            plain = [r for r in rules if rule_matches(r, tag, classes, False, ancestors)]
            with_state = [r for r in rules if rule_matches(r, tag, classes, True, ancestors)]
            states = [(False, plain)] + ([(True, with_state)]
                                         if any(r["stateful"] for r in with_state) else [])
            for stateful, matched in states:
                col, bg = colour, ground
                own_col = winner(matched, ("color",))
                bound_col = _contrast_bound(node, "color")
                if bound_col is not None:
                    col = bound_ref(bound_col)
                elif own_col not in (None, "inherit", "currentColor"):
                    col = _contrast_name(own_col)
                elif own_col is None and tag in ("a", "button") and node["text"]:
                    raise ValueError("no colour rule for a text-bearing " + tag)
                bound_bg = _contrast_bound(node, "background")
                own_bg = winner(matched, ("background", "background-color"))
                if bound_bg is not None:
                    bg = (bound_ref(bound_bg) or "?" + bound_bg,) + ground
                elif own_bg is not None:
                    bg = ground_of(own_bg, ground)
                elif tag == "button":
                    raise ValueError("no background rule for a button")
                if node["text"] and col is not None:
                    raw.add((col, bg))
                for pseudo in _CONTRAST_PSEUDO_ELEMENTS:
                    pm = [r for r in rules
                          if rule_matches(r, tag, classes, stateful, ancestors, pseudo)]
                    pseudo_col = winner(pm, ("color",))
                    if pseudo_col and col is not None:
                        raw.add((_contrast_name(pseudo_col), bg))
                for kid in node["kids"]:
                    visit(kid, ancestors + [(tag, classes, stateful)], col, bg)

    body = [r for r in rules if rule_matches(r, "body", frozenset(), False, [])]
    visit(_contrast_tree(root_src), [("body", frozenset(), False)],
          _contrast_name(winner(body, ("color",)) or ""),
          ground_of(winner(body, ("background", "background-color")) or "", ()))
    return {pair for fg, ground in raw
            for pair in _contrast_resolve(fg, ground, tables)}


def _contrast_resolve(fg: str, ground: tuple[str, ...],
                      tables: dict[str, dict]) -> list[tuple[str, tuple[str, ...]]]:
    """A derived pairing with its bound references (`@it.tint`) replaced by every
    row of the table they read — one row per table at a time, so two bindings on
    the same row stay together — and its ground cut at the first opaque layer.
    A row with no value for a bound ground (a tint of 'none') lets the layer
    below show through; a row with no value for a bound colour paints no text."""
    if any(layer.startswith("?") for layer in ground):
        raise ValueError("text on an unresolved bound ground: %r" % (ground,))
    heads = sorted({ref[1:].rpartition(".")[0]
                    for ref in (fg,) + ground if ref.startswith("@")})
    import itertools
    rows = [list(tables[h].values()) for h in heads]
    out = []
    for combo in itertools.product(*rows):
        env = dict(zip(heads, combo))

        def val(ref):
            if not ref.startswith("@"):
                return ref
            head, _, field = ref[1:].rpartition(".")
            v = str(env[head].get(field) or "").strip()
            return "" if v in ("none", "transparent") else _contrast_name(v)

        colour = val(fg)
        if not colour:
            continue
        layers = [x for x in (val(g) for g in ground) if x]
        cut = []
        for layer in layers:
            cut.append(layer)
            if not layer.startswith(("rgba(", "color-mix(")):
                break
        out.append((colour, tuple(cut)))
    return out


def _contrast_layer(value: str, palette: dict, theme: str) -> tuple[tuple[int, int, int], float]:
    """One layer of a pair as (sRGB, opacity) in `theme`: a palette role, a hex,
    an rgba(), or a color-mix() of a hex with transparent. Raises on anything
    else, so a value the floor cannot read is never silently opaque."""
    if value.startswith("--"):
        rgb = _hex_rgb(palette[value][theme])
    elif value.startswith("rgba("):
        r, g, b, a = (x.strip() for x in value[5:-1].split(","))
        return (int(r), int(g), int(b)), float(a)
    elif value.startswith("color-mix("):
        m = re.fullmatch(r"color-mix\(in srgb,\s*(#[0-9A-Fa-f]{6})\s+([\d.]+)%,\s*transparent\)",
                         value)
        if not m:
            raise ValueError(value)
        return _hex_rgb(m.group(1)), float(m.group(2)) / 100
    else:
        rgb = _hex_rgb(value)
    if rgb is None:
        raise ValueError(value)
    return rgb, 1.0


def _pair_ratio(fg: str, ground: tuple[str, ...], palette: dict, theme: str) -> float:
    """The WCAG 2 contrast of `fg` on `ground` in `theme`, the ground's alpha
    layers composited from the opaque one up."""
    layers = [_contrast_layer(v, palette, theme) for v in ground]
    if not layers or layers[-1][1] != 1.0:
        raise ValueError("a ground with no opaque layer: %r" % (ground,))
    rgb = layers[-1][0]
    for colour, share in reversed(layers[:-1]):
        rgb = _over(colour, share, rgb)
    return _contrast(_contrast_layer(fg, palette, theme)[0], rgb)


def _contrast_rows(pairs, palette: dict) -> list[tuple[str, tuple[str, ...], float, float]]:
    """Each pair with its dark and its light ratio, lowest dark ratio first —
    what --contrast-report prints and what the floor reads (the dark column)."""
    rows = [(fg, ground, _pair_ratio(fg, ground, palette, "dark"),
             _pair_ratio(fg, ground, palette, "light")) for fg, ground in pairs]
    return sorted(rows, key=lambda r: (r[2], r[0], r[1]))


def _contrast_report(derived, table, palette: dict, floor: float) -> list[str]:
    """What --contrast-report prints: a header, then one line per derived pair
    with its dark and light ratio, a line marked when its dark ratio is under
    the floor or when the pair is missing from `table`."""
    lines = ["  dark  light  pair   (floor %.1f:1 on dark; light not enforced)" % floor]
    for fg, ground, dark, light in _contrast_rows(derived, palette):
        marks = (["below floor"] if dark < floor else []) + (
            ["not in _CONTRAST_PAIRS"] if (fg, ground) not in table else [])
        lines.append("%6.2f %6.2f  %s on %s%s" % (
            dark, light, fg, " over ".join(ground),
            "   <- " + ", ".join(marks) if marks else ""))
    return lines


@_covers("palette-dark-follows-the-dark-rule", kind="behaviour",
         breaks=[
             # hue: --mut's dark value turned 21 degrees toward cyan at the same
             # lightness and saturation, still clearing the floor on every dark
             # ground, so only the hue tolerance can catch it
             lambda c: {"palette": dict(c["palette"], **{"--mut": dict(
                 c["palette"]["--mut"], dark="#94A1A8")})},
             # the floor: --accent left at its light value in the dark theme —
             # same hue, same saturation, no lift, so only the 4.5:1 floor on
             # the dark grounds can catch it (--accent has no soft of its own)
             lambda c: {"palette": dict(c["palette"], **{"--accent": dict(
                 c["palette"]["--accent"], dark=c["palette"]["--accent"]["light"])})},
             # a soft ground that is not its state at 14% over the dark card —
             # darker, so the green on it still clears the floor and only the
             # soft's mix can catch it
             lambda c: {"palette": dict(c["palette"], **{"--green-soft": dict(
                 c["palette"]["--green-soft"], dark="#253B49")})},
             # a named family reuse broken: --halt-line keeping its light value
             lambda c: {"palette": dict(c["palette"], **{"--halt-line": dict(
                 c["palette"]["--halt-line"], dark=c["palette"]["--halt-line"]["light"])})},
             # a fixed role that moved between themes
             lambda c: {"palette": dict(c["palette"], **{"--hat": dict(
                 c["palette"]["--hat"], dark="#F5A624")})},
             # the swap: --now no longer following the dark ink
             lambda c: {"palette": dict(c["palette"], **{"--now": dict(
                 c["palette"]["--now"], dark="#F6F3ED")})},
         ])
def _c_palette_dark_rule(ctx):
    """The dark palette is DERIVED from the light one by the plan's dark rule,
    and holds to it: grounds and ink swap; each lifted text or state role keeps
    its light hue (within 2 degrees) and saturation (within 0.02) and only rises
    in HLS lightness, clearing 4.5:1 on the three dark grounds and on its own
    soft; each soft is its state's dark colour at 14% over the dark card, the
    in-flight soft the dark ink at 10%; the named family reuses repeat their
    family's dark value; and the fixed roles keep one value in both themes.

    Say what this does not establish: "rises UNTIL it clears" also means it
    rises no further than it has to, and minimality is not checked — a dark
    value lifted past the floor still passes. The floor here covers the rule's
    own pairings only; every pairing the stylesheet actually paints is
    dark-text-pairs-clear-the-floor's claim, not this one's."""
    import colorsys
    pal, rule = ctx["palette"], ctx["dark_rule"]
    light = {n: _hex_rgb(v["light"]) for n, v in pal.items()}
    dark = {n: _hex_rgb(v["dark"]) for n, v in pal.items()}
    if not pal or None in light.values() or None in dark.values():
        return False
    try:
        for role, (theme, source) in rule["swaps"].items():
            if dark[role] != (light if theme == "light" else dark)[source]:
                return False
        grounds = [dark[g] for g in rule["grounds"]]
        for role, soft in rule["lifted"].items():
            hl, ll, sl = colorsys.rgb_to_hls(*(c / 255 for c in light[role]))
            hd, ld, sd = colorsys.rgb_to_hls(*(c / 255 for c in dark[role]))
            turn = abs(hl - hd) * 360
            if (min(turn, 360 - turn) > rule["hue_tol"]
                    or abs(sl - sd) > rule["sat_tol"] or ld < ll):
                return False
            if any(_contrast(dark[role], g) < rule["floor"]
                   for g in grounds + ([dark[soft]] if soft else [])):
                return False
        for soft, (family, share) in rule["softs"].items():
            want = _over(dark[family], share, dark[rule["soft_ground"]])
            if any(abs(a - b) > 1 for a, b in zip(want, dark[soft])):
                return False
        if any(dark[r] != dark[s] for r, s in rule["reuses"].items()):
            return False
        if any(light[r] != dark[r] for r in rule["fixed"]):
            return False
        return all(_contrast(dark[fg], dark[bg]) >= rule["floor"]
                   for fg, bg in rule["fixed_pairs"])
    except KeyError:
        return False


def _contrast_derive_ctx(c: dict, css: str) -> set:
    """The pairs the walk derives from `css` against the context's own templates
    and bound tables — what a control that edits the sheet compares against."""
    return _contrast_pairs_derived(css, c["app_src"],
                                   {"it": c["state_meta"], "w.step": c["wave_lanes"]})


@_covers("wcag-contrast-known-answers", kind="behaviour",
         breaks=[
             # a ratio taken on the raw 0..255 channels, without the sRGB
             # linearisation: black on white still comes out 21, so only the
             # published mid-grey pairs can catch it
             lambda c: {"contrast_fn": lambda a, b: (
                 (max(sum(a), sum(b)) / 765 + 0.05) / (min(sum(a), sum(b)) / 765 + 0.05))},
             # compositing that ignores the alpha share and paints the layer
             # opaque: the known contrasts hold, only the half-white mix fails
             lambda c: {"over_fn": lambda fg, share, ground: tuple(fg)},
         ])
def _c_wcag_contrast_known_answers(ctx):
    """The floor's arithmetic, against answers fixed outside this file: WCAG 2.x
    relative luminance gives black on white 21:1, and the published grey #767676
    on white 4.54:1 — the lightest grey that passes 4.5:1 — while #777777, one
    step lighter, gives 4.48:1 and fails. The ratio is symmetric. Compositing
    white at half opacity over black lands on #808080 (128 per channel)."""
    contrast, over = ctx["contrast_fn"], ctx["over_fn"]
    white, black = (255, 255, 255), (0, 0, 0)
    return (abs(contrast(black, white) - 21.0) < 1e-9
            and round(contrast((0x76,) * 3, white), 2) == 4.54
            and round(contrast((0x77,) * 3, white), 2) == 4.48
            and contrast((0x77,) * 3, white) < 4.5 <= contrast((0x76,) * 3, white)
            and contrast(white, (0x76,) * 3) == contrast((0x76,) * 3, white)
            and over(white, 0.5, black) == (128, 128, 128))


@_covers("dark-text-pairs-clear-the-floor", kind="behaviour",
         breaks=[
             # one dark value lowered one step below the floor: --mut's dark
             # value one HLS-lightness step down, 4.48:1 on --steel-soft. The
             # pairs are unchanged, so only the floor can catch it
             lambda c: {"palette": dict(c["palette"], **{"--mut": dict(
                 c["palette"]["--mut"], dark="#A0A5B2")})},
             # a stylesheet pairing missing from the table: the table without
             # --mut on --surface-2, every other pair as derived
             lambda c: {"contrast_pairs": tuple(
                 p for p in c["contrast_pairs"] if p != ("--mut", ("--surface-2",)))},
             # the stylesheet paints a pairing the table does not hold: the
             # notices kind recoloured --green on the page ground (6.9:1, clear
             # of the floor), so the walk gains that pair and loses the --wait
             # one, and only the table's equality can catch it
             lambda c: {"css": c["css"] + "\n.notices__kind{ color:var(--green); }"},
             # an alpha ground composited for real: the command line's 8% white
             # over the band raised to 88%, the table re-derived to match, so the
             # white text on it fails the floor only through the compositing — a
             # walk that read the band beneath would still pass
             lambda c: (lambda css: {"css": css, "contrast_pairs": tuple(
                 sorted(_contrast_derive_ctx(c, css)))})(c["css"].replace(
                     "background:rgba(255,255,255,.08)", "background:rgba(255,255,255,.88)", 1)),
             # the named pair gone from the page: every --surface-2 ground read
             # as --surface and the table re-derived to match, so table and
             # floor both hold and only the required pair can catch it
             lambda c: (lambda css: {"css": css, "contrast_pairs": tuple(
                 sorted(_contrast_derive_ctx(c, css)))})(
                     c["css"].replace("var(--surface-2)", "var(--surface)")),
             # the item card's tint read off the state table: every state
             # untinted, so the card's text falls through to the lane's soft,
             # the walk's pairs on the state softs change, and the table no
             # longer equals it — a walk that ignored the binding would not move
             lambda c: {"state_meta": {k: dict(v, tint="none")
                                       for k, v in c["state_meta"].items()}},
         ])
def _c_dark_text_pairs_clear_the_floor(ctx):
    """Every text-on-ground pairing the finished page paints clears 4.5:1 in the
    dark palette by WCAG 2.x relative luminance, alpha grounds composited over
    the ground they sit on.

    The pairs are derived, not listed: _contrast_pairs_derived walks the
    stylesheet's cascade over the page's templates (its docstring names what it
    reads and every place it stops), and _CONTRAST_PAIRS must EQUAL what it
    finds, so a pairing the sheet paints and the table lacks fails, and so does
    a stale entry the sheet no longer paints. The pairs in _CONTRAST_REQUIRED —
    --mut on --surface-2 — must be among them. Only the dark column is held to
    the floor; the light palette is the approved design, reported by
    --contrast-report and never enforced, which the last line proves by
    sinking every light value onto the light page ground and still passing.

    What this does not establish: text whose colour is bound inline to anything
    but a row of the state or wave-lane table (a state pill, a repo chip) is
    not read, because no stylesheet rule gives it that colour; and a browser's
    own rendering — anti-aliasing, a font's weight — is the gate's screenshot,
    not this check."""
    floor = ctx["dark_rule"]["floor"]
    try:
        derived = _contrast_derive_ctx(ctx, ctx["css"])
        table = set(ctx["contrast_pairs"])
        if not derived or derived != table or len(table) != len(ctx["contrast_pairs"]):
            return False
        if any(req not in derived for req in ctx["contrast_required"]):
            return False
        if any(dark < floor for _, _, dark, _ in _contrast_rows(table, ctx["palette"])):
            return False
        sunk = {n: dict(v, light=ctx["palette"]["--bg"]["light"])
                for n, v in ctx["palette"].items()}
        return all(dark >= floor for _, _, dark, _ in _contrast_rows(table, sunk))
    except (KeyError, ValueError):
        return False


@_covers("contrast-report-marks-what-the-floor-refuses", kind="behaviour",
         breaks=[
             # a report that never marks a line
             lambda c: {"contrast_report_fn": lambda d, t, p, f: [
                 ln.split("   <- ")[0] for ln in _contrast_report(d, t, p, f)]},
             # a report that drops the light column
             lambda c: {"contrast_report_fn": lambda d, t, p, f: [
                 ln if i == 0 else ln[:7] + ln[14:]
                 for i, ln in enumerate(_contrast_report(d, t, p, f))]},
         ])
def _c_contrast_report_marks(ctx):
    """--contrast-report prints one line per derived pair carrying both ratios,
    dark then light, and marks a line only when the floor would refuse it: the
    true page prints no mark; --mut's dark value sunk onto the dark card marks
    each --mut line 'below floor'; a table without --mut on --surface-2 marks
    that one line 'not in _CONTRAST_PAIRS'. Nothing else is marked — the light
    column is printed, never judged."""
    report, palette, floor = ctx["contrast_report_fn"], ctx["palette"], ctx["dark_rule"]["floor"]
    derived, table = _contrast_derive_ctx(ctx, ctx["css"]), set(ctx["contrast_pairs"])
    true = report(derived, table, palette, floor)
    if len(true) != len(derived) + 1 or any("<-" in ln for ln in true):
        return False
    if not all(re.match(r"\s*\d+\.\d\d\s+\d+\.\d\d  ", ln) for ln in true[1:]):
        return False
    sunk = dict(palette, **{"--mut": dict(palette["--mut"], dark=palette["--surface"]["dark"])})
    low = [ln for ln in report(derived, table, sunk, floor) if "<-" in ln]
    if not low or not all(" --mut on " in ln and "below floor" in ln for ln in low):
        return False
    missing = [ln for ln in report(derived, table - {("--mut", ("--surface-2",))},
                                   palette, floor) if "<-" in ln]
    return (len(missing) == 1 and " --mut on --surface-2" in missing[0]
            and "not in _CONTRAST_PAIRS" in missing[0])


