@_covers("repo-word-mirrors-the-card-word", kind="behaviour",
         breaks=[lambda c: {"repo_word": lambda feed: "NEXT"},
                 lambda c: {"repo_word": lambda feed: c["repo_word"](dict(feed, archived=[]))},
                 lambda c: {"is_degraded_feed": lambda feed: False},
                 lambda c: {"is_degraded_feed": lambda feed: bool((feed or {}).get("errors"))},
                 lambda c: {"app_src": c["app_src"].replace(
                     " + archived.length;\n  const level", ";\n  const level", 1)},
                 lambda c: {"repo_inlined": dict(c["repo_inlined"], degraded_prefix="engine down — ")},
                 # the shape match made key-order dependent: the polled feed
                 # arrives with sorted keys and REPO.degraded in insertion
                 # order, so without the sort a wedged feed never matches
                 lambda c: {"app_src": c["app_src"].replace(
                     "Object.keys(v).sort().map(", "Object.keys(v).map(", 1)},
                 # the fact that makes the sort necessary, broken: a feed
                 # served in insertion order would let an unsorted compare pass
                 lambda c: {"state_body": lambda payload: (json.dumps(payload), None)},
                 lambda c: {"py_twins": dict(c["py_twins"], repo_word="def repo_word(): pass")}])
def _c_repo_word_mirrors_card(ctx):
    """The word a polled feed earns is the word the server's card gives the
    same state: _repo_card(state) and repoWordOf's twin over split_archived
    (state) agree over every case — a wedged engine and its degraded feed, an
    empty repo (NEXT, never CLEAR), a running build, a waiting one, and
    all-archived repos at level cleanup and at level blocked (both CLEAR,
    counting the archived entries a poll carries as merged rows). WEDGED is
    read off the exact _degraded_state shape and nothing looser: one extra key,
    or a reworded line, is a healthy feed. The page's copies carry the same
    branch and the server hands them the degraded shape from _degraded_state
    itself. The page's shape match compares canonical JSON, whose key sort is
    load-bearing: the polled feed arrives with sorted keys while the inlined
    degraded shape keeps insertion order, and both facts are read here."""
    card, word, split = ctx["repo_card"], ctx["repo_word"], ctx["split_archived"]
    degraded, is_deg = ctx["degraded_state"], ctx["is_degraded_feed"]

    def row(slug, status, archived=False):
        return {"slug": slug, "status": status, "archived": archived,
                "items": {"total": 1, "done": 1 if status == "merged" else 0, "detail": []}}

    def st(binders, level):
        return {"repo": {"default_branch": "main"}, "order": None, "binders": binders,
                "next_action": {"level": level, "command": None, "human": level},
                "warnings": [], "errors": []}

    cases = [ctx["derive_state"]([], {"default_branch": "main", "binders": {}}),
             st([row("a", "in_flight"), row("b", "merged")], "item"),
             st([row("a", "not_started")], "binder"),
             st([row("a", "merged", True), row("b", "merged", True)], "cleanup"),
             st([row("a", "merged", True)], "blocked"),
             st([row("a", "merged"), row("b", "not_started")], "binder")]
    words = []
    for state in cases:
        want = card("s", "/r", {"ok": True, "state": state, "error": None, "activity": None})["word"]
        if word(split(state)) != want:
            return False
        words.append(want)
    if words != ["NEXT", "NOW", "NEXT", "CLEAR", "CLEAR", "NEXT"]:
        return False
    wedged = card("s", "/r", {"ok": False, "state": None, "error": "x", "activity": None})["word"]
    feed = split(degraded("x"))
    if wedged != "WEDGED" or word(feed) != "WEDGED" or not is_deg(feed):
        return False
    if is_deg(dict(feed, extra=1)) or is_deg(dict(feed, errors=["x", "y"])):
        return False
    reworded = dict(feed, next_action=dict(feed["next_action"], human="engine fine — x"))
    if is_deg(reworded) or word(reworded) == "WEDGED":
        return False
    table = ctx["repo_inlined"] or {}
    if (table.get("degraded") != split(degraded(""))
            or table.get("degraded_prefix") != degraded("")["next_action"]["human"]):
        return False
    # Why canonicalJson sorts keys: the two sides it compares arrive in
    # different key orders. The polled feed is served pinned — sorted keys —
    # while REPO.degraded is inlined unpinned, in _degraded_state's insertion
    # order. Both facts are read here, so dropping the sort fails for the
    # reason it would break the page: a wedged feed would never match.
    served = list(json.loads(ctx["state_body"](split(degraded("x")))[0]))
    inlined = list((ctx["repo_inlined"] or {}).get("degraded") or {})
    if served != sorted(served) or inlined == sorted(inlined) or set(served) != set(inlined):
        return False
    app, py = ctx["app_src"], ctx["py_twins"]
    canon = _js_block(app, "function canonicalJson(v) {")
    if not all(f in canon for f in (
            "if (Array.isArray(v)) return '[' + v.map(canonicalJson).join(',') + ']';",
            "Object.keys(v).sort().map(k => JSON.stringify(k) + ':' + canonicalJson(v[k]))")):
        return False
    word_js = _js_block(app, "function repoWordOf(s) {")
    deg_js = _js_block(app, "function isDegradedFeed(s) {")
    if not _js_first_after_brace(word_js, "function repoWordOf(s) {", "if (isDegradedFeed(s)) return 'WEDGED';"):
        return False
    return (all(f in word_js for f in ("filter(b => b.status === 'merged').length + archived.length",
                                       "b.status === 'in_flight'", "level === 'done'",
                                       "total && merged === total", "return 'NEXT';"))
            and "UNAVAILABLE" not in word_js
            and all(f in deg_js for f in ("errors.length !== 1", "REPO.degraded",
                                          "REPO.degraded_prefix + errors[0]", "canonicalJson(s) === canonicalJson(want)"))
            and "MIRROR: change together with repo_word()" in app
            and "MIRROR: change together with is_degraded_feed()" in app
            and "MIRROR: change together with repoWordOf()" in py.get("repo_word", "")
            and "MIRROR: change together with isDegradedFeed()" in py.get("is_degraded_feed", ""))


@_covers("wedged-repo-recovers-on-the-next-poll", kind="behaviour",
         breaks=[lambda c: {"poll_plan": lambda feeds, search: [
                     p for p in c["poll_plan"](feeds, search) if feeds[p["i"]]["word"] != "WEDGED"]},
                 lambda c: {"app_src": c["app_src"].replace(
                     "              feed.word = repoWordOf(s);\n", "", 1)},
                 lambda c: {"app_src": c["app_src"].replace(
                     "if (r.status === 304) return 304;",
                     "if (r.status === 304) { feed.word = 'NEXT'; return 304; }", 1)}])
def _c_wedged_repo_recovers(ctx):
    """A wedged repo is polled like any other, so it does not stay wedged on
    screen once its engine recovers. Its feed is in the plan; the cycle that
    finds it healthy recomputes its word from what came back — WEDGED to the
    healthy word — and a 304 leaves the word as the last answer set it. The
    feed's move from degraded to healthy is driven through the twins: the
    plan asks it, and the word follows the payload."""
    feeds = _plan_feeds(["WEDGED"])
    if [p["i"] for p in ctx["poll_plan"](feeds, "?key=T")] != [0]:
        return False
    word, split = ctx["repo_word"], ctx["split_archived"]
    before = split(ctx["degraded_state"]("git wedged"))
    after = split(ctx["state"])
    if word(before) != "WEDGED" or word(after) != "NOW":
        return False
    poll = _js_block(ctx["app_src"], "    poll() {")
    if "feed.word = repoWordOf(s);" not in poll or "if (r.status === 304) return 304;" not in poll:
        return False
    return (poll.index("if (r.status === 304) return 304;") < poll.index("feed.word = repoWordOf(s);")
            < poll.index("feed.state = this.withArchived(feed, s);")
            and poll.count("feed.word") == 1)


@_covers("unavailable-repo-is-never-polled", kind="behaviour",
         breaks=[lambda c: {"poll_plan": lambda feeds, search: [
                     {"i": i, "url": f["url"] + search, "etag": f.get("etag")} for i, f in enumerate(feeds)]},
                 lambda c: {"all_roster": [dict(r, state={"binders": []}) if r["word"] == "UNAVAILABLE" else r
                                           for r in c["all_roster"]]},
                 lambda c: {"app_src": c["app_src"].replace(
                     "function repoWordOf(s) {\n", "function repoWordOf(s) {\n  if (!s) return 'UNAVAILABLE';\n", 1)}])
def _c_unavailable_never_polled(ctx):
    """A repo the server inlined UNAVAILABLE keeps that word until the page
    reloads and is never polled: its path is gone, so its feed would only read
    as WEDGED. The roster carries no state for it — nothing to seed a feed
    with — the plan skips it, and the word a poll can set is never that one."""
    feeds = _plan_feeds(["UNAVAILABLE", "NOW", "UNAVAILABLE"])
    if [p["i"] for p in ctx["poll_plan"](feeds, "?key=T")] != [1]:
        return False
    gone = [r for r in ctx["all_roster"] if r["word"] == "UNAVAILABLE"]
    if len(gone) != 1 or gone[0]["state"] is not None:
        return False
    word_js = _js_block(ctx["app_src"], "function repoWordOf(s) {")
    return bool(word_js) and "UNAVAILABLE" not in word_js


@_covers("cross-repo-builds-carry-repo-name-and-chip", kind="behaviour",
         breaks=[lambda c: {"repos_of": lambda feeds: [{"name": f.get("name") or "", "state": f.get("state") or {}}
                                                       for f in feeds]},
                 lambda c: {"repo_lines": lambda feeds: []},
                 lambda c: {"page": c["page"].replace(
                     'data-kw-repo-chip v-if="multi"', "data-kw-repo-chip", 1)},
                 lambda c: {"page": c["page"].replace(
                     'v-for="r in repoLines"', 'v-for="r in repoLines.slice(1)"', 1)},
                 lambda c: {"app_src": c["app_src"].replace(
                     "repos() { return reposOf(this.feeds); },",
                     "repos() { return this.feeds; },", 1)},
                 lambda c: {"app_src": c["app_src"].replace(
                     "  const shown = all.length > 1 ? all.filter(", "  const shown = all.length > 0 ? all.filter(", 1)},
                 # a wedged repo's line read off the note it was inlined with,
                 # not the error its own feed now carries
                 lambda c: {"repo_lines": lambda feeds: [
                     dict(l, line=next(f for f in feeds if f["slug"] == l["slug"])["note"])
                     if l["word"] == "WEDGED" else l for l in c["repo_lines"](feeds)]},
                 lambda c: {"app_src": c["app_src"].replace(
                     "line = (word === 'WEDGED' && errors.length) ? errors[0] : (f.note || '');",
                     "line = f.note || '';", 1)},
                 # a healthy repo's next action shown only when its level is empty
                 lambda c: {"repo_lines": lambda feeds: [
                     dict(l, line="") if l["word"] not in ("WEDGED", "UNAVAILABLE") and (
                         (next(f for f in feeds if f["slug"] == l["slug"])["state"].get("next_action") or {})
                         .get("level") != "empty") else l
                     for l in c["repo_lines"](feeds)]}])
def _c_cross_repo_builds_carry_chip(ctx):
    """With more than one repo watched, each repo's builds carry its name and
    its chip, and a repo with no build row shows its chip in My builds in
    place of builds — a WEDGED repo's line is the error its own feed carries
    (the note it was inlined with only when the feed carries none), an
    UNAVAILABLE repo's is its note, and a healthy one's is the engine's next
    action at any level, the plan-first line when it is empty — and
    contributes nothing to the
    other squares, the views or the headline. Driven over the multi-repo hub
    fixture, which watches one empty repo: the twins hand the home models only
    the repo with builds (the headline counts its builds alone and no
    needs-you row comes from the others), and one line per repo with no build.
    A page watching one repo hands it through as it is and draws no chip."""
    feeds = [dict(r, url="", etag=None, state=r["state"] or {"binders": []})
             for r in ctx["all_roster"]]
    shown = ctx["repos_of"](feeds)
    if [r["name"] for r in shown] != [r["name"] for r in ctx["all_roster"]
                                      if (r["state"] or {}).get("binders")]:
        return False
    quiet = {r["name"] for r in ctx["all_roster"] if not (r["state"] or {}).get("binders")}
    whole = [{"name": f["name"], "state": f["state"]} for f in feeds]
    if (not any(row["repo"] in quiet for row in ctx["needs_you"](whole))
            or any(row["repo"] in quiet for row in ctx["needs_you"](shown))):
        return False
    if ctx["home_headline"](shown) != ctx["home_headline"](
            [{"name": r["name"], "state": r["state"]} for r in feeds if r["word"] in ("NOW", "CLEAR")]):
        return False
    lines = {l["word"]: l for l in ctx["repo_lines"](feeds)}
    if set(lines) != {"NEXT", "WEDGED", "UNAVAILABLE"}:
        return False
    wedged = next(f for f in feeds if f["word"] == "WEDGED")
    if wedged["note"] == wedged["state"]["errors"][0]:
        return False                       # the fixture must tell the two apart
    if (lines["WEDGED"]["line"] != wedged["state"]["errors"][0]
            or lines["UNAVAILABLE"]["line"] != "repo path no longer exists"
            or lines["NEXT"]["line"] != hatch_next.EMPTY_HUMAN):
        return False
    # a wedged repo whose feed carries no error falls back to its note, and a
    # healthy repo with no build at a level other than empty still shows its
    # next action
    bare = dict(wedged, slug="bare", state={"binders": []})
    erring = {"slug": "erring", "name": "erring", "word": "NEXT", "note": "", "url": "", "etag": None,
              "state": {"binders": [], "errors": ["binder.json: bad JSON"],
                        "next_action": {"level": "error", "command": None, "human": "fix the binder"}}}
    extra = {l["slug"]: l["line"] for l in ctx["repo_lines"]([bare, erring])}
    if extra != {"bare": wedged["note"], "erring": "fix the binder"}:
        return False
    lines_js = _js_block(ctx["app_src"], "function repoLinesOf(feeds) {")
    if not all(f in lines_js for f in (
            "line = (word === 'WEDGED' && errors.length) ? errors[0] : (f.note || '');",
            "line = (state.next_action || {}).human || '';")):
        return False
    hub = [dict(r, url="", etag=None, state=r["state"]) for r in ctx["hub_roster"]]
    if ([r["name"] for r in ctx["repos_of"](hub)] != ["alpha", "beta"]
            or [l["name"] for l in ctx["repo_lines"](hub)] != ["gamma"]):
        return False
    one = feeds[1:2]
    if ctx["repos_of"](one) != [{"name": one[0]["name"], "state": one[0]["state"]}] or ctx["repo_lines"](one):
        return False
    page = ctx["page"]
    builds = _tags_with(page, 'data-kw-square')
    square = _subtree(page, builds[0]) if builds else ""
    names = _tags_with(page, "data-kw-home-build-repo")
    chips = _tags_with(page, "data-kw-repo-chip")
    lines_t = _tags_with(page, "data-kw-repo-line")
    if len(names) != 1 or len(chips) != 2 or len(lines_t) != 1:
        return False
    if not all(t in square for t in names + chips + lines_t):
        return False
    row = _tags_with(page, "data-kw-home-build")[0]
    if names[0] not in _subtree(page, row) or chips[0] not in _subtree(page, row):
        return False
    if _attrs(names[0]).get("v-if") != "multi" or _attrs(chips[0]).get("v-if") != "multi":
        return False
    line = _attrs(lines_t[0])
    if (line.get("v-for") != "r in repoLines" or line.get(":data-kw-repo-line-slug") != "r.slug"
            or chips[1] not in _subtree(page, lines_t[0])):
        return False
    app, py = ctx["app_src"], ctx["py_twins"]
    return ("repos() { return reposOf(this.feeds); }," in app
            and "repoLines() { return repoLinesOf(this.feeds); }," in app
            and "multi() { return this.feeds.length > 1; }," in app
            and "const shown = all.length > 1 ? all.filter(" in _js_block(app, "function reposOf(feeds) {")
            and "if (all.length < 2) return [];" in _js_block(app, "function repoLinesOf(feeds) {")
            and "MIRROR: change together with reposOf()" in py.get("repos_of", "")
            and "MIRROR: change together with repoLinesOf()" in py.get("repo_lines", ""))


@_covers("hub-home-inlines-the-roster", kind="behaviour",
         breaks=[lambda c: {"hub": c["hub"].replace("window.__HATCH_REPOS__", "window.__HATCH_ROSTER__", 1)},
                 lambda c: {"watched_repos": lambda cards, engine_for: [
                     {"slug": x["slug"], "name": x["name"], "word": x["word"], "note": x["note"], "state": None}
                     for x in cards]},
                 lambda c: {"app_src": c["app_src"].replace(
                     "<span class=\"hrow__name\">{{ b.name }}</span>",
                     "<span class=\"hrow__name\" v-html=\"b.name\"></span>", 1)},
                 lambda c: {"hub_dispatch": c["hub_dispatch"].replace("watched_repos(", "x(", 1)},
                 lambda c: {"render_hub": lambda roster: c["render_hub"](roster).replace(
                     "\\u003c", "<")}])
def _c_hub_home_inlines_roster(ctx):
    """The hub / is the app document, seeded from the roster hub_cards built:
    one entry per card, carrying its slug, word and note, a name no other entry
    shares, and the state that repo's RepoEngine has just cached — read through
    the same .state() call, so no derivation runs twice inside the window — or
    the degraded state for a wedged repo, and nothing for a gone one. Inlined
    through _inert_json, so a hostile repo name carries no markup byte into the
    page; an archived build arrives with its title, summary, items, item words
    and review, which is what seeds archivedDetail; and no state-derived string
    reaches v-html anywhere in the app."""
    if ctx["hub_repos_inlined"] != ctx["hub_roster"] or _inlined_repos(ctx["hub"]) != ctx["hub_roster"]:
        return False
    beta = next(r for r in _inlined_repos(ctx["hub"]) if r["name"] == "beta")
    old = beta["state"]["binders"][0]
    if not (old.get("archived") and old.get("title") and old.get("summary")
            and old["items"]["detail"] and "review" in old):
        return False
    hostile = [{"slug": "x-00000000", "name": "<img src=x onerror=alert(1)>", "word": "WEDGED",
                "note": "<script>alert('n')</script>", "state": None}]
    doc = ctx["render_hub"](hostile)
    if "<img src=x" in doc or "<script>alert" in doc or _inlined_repos(doc) != hostile:
        return False
    calls = []

    class _Eng:
        def __init__(self, res):
            self.res = res

        def state(self):
            calls.append(1)
            return self.res

    live = {"ok": True, "state": ctx["state"], "error": None, "activity": None}
    broke = {"ok": False, "state": None, "error": "git wedged", "activity": None}
    cards = [{"slug": "a-1", "root": "/a", "name": "same", "word": "NOW", "note": ""},
             {"slug": "b-2", "root": "/b", "name": "same", "word": "WEDGED", "note": "git wedged"},
             {"slug": "c-3", "root": "/c", "name": "gone", "word": "UNAVAILABLE", "note": "gone"}]
    engines = {"/a": _Eng(live), "/b": _Eng(broke)}
    got = ctx["watched_repos"](cards, lambda root: engines[root])
    if [sorted(e) for e in got] != [["name", "note", "slug", "state", "word"]] * 3:
        return False
    if ([e["name"] for e in got] != ["a-1", "b-2", "gone"]
            or got[0]["state"] is not ctx["state"]
            or got[1]["state"] != ctx["degraded_state"]("git wedged")
            or got[2]["state"] is not None or len(calls) != 2):
        return False
    src = ctx["hub_dispatch"]
    home = src[src.index('path in ("/", "/index.html")'):src.index("_REPO_ROUTE.fullmatch")]
    if not all(call in home for call in ("hub_cards(", "watched_repos(", "render_app_html(",
                                         "watched=watched")):
        return False
    if not home.index("hub_cards(") < home.index("watched_repos(") < home.index("render_app_html("):
        return False
    feed_js = _js_block(ctx["app_src"], "function feedOf(r, url) {")
    return ("v-html" not in ctx["app_src"]
            and "if (b && b.archived) archivedDetail[b.slug] = b;" in feed_js
            and "roster.map(r => feedOf(r, '/r/' + r.slug + '/state.json'))" in ctx["app_src"])


@_covers("open-build-is-found-in-its-own-repo", kind="behaviour",
         breaks=[lambda c: {"shown_feed": lambda feeds, slug, repo: c["shown_feed"](feeds, slug, None)},
                 lambda c: {"app_src": c["app_src"].replace(
                     "if (action === 'open') this.binderRepo = (repo === undefined) ? null : repo;", "", 1)},
                 lambda c: {"page": c["page"].replace(
                     _tags_with(c["page"], "data-kw-home-build")[0],
                     _tags_with(c["page"], "data-kw-home-build")[0].replace(
                         "go('open', b.slug, b.repo)", "go('open', b.slug)"), 1)},
                 lambda c: {"page": c["page"].replace(
                     ":key=\"p.repo + '/' + p.slug\"", ":key=\"p.slug\"", 1)},
                 lambda c: {"app_src": c["app_src"].replace(
                     "strip() { return stripPillsOf(this.feeds); },",
                     "strip() { return runningStripOf(this.allBinders); },", 1)},
                 lambda c: {"py_twins": dict(c["py_twins"], shown_feed="def shown_feed(): pass")}])
def _c_open_build_in_its_own_repo(ctx):
    """A build on the cross-repo home is named by its repo AND its slug: two
    watched repos may each hold a build with the same slug, and opening the
    second repo's must show the second repo's build, with its next step and
    notices. So a My builds row and a strip pill both open with the repo they
    came from, the page records that repo with the open build, the feed it is
    shown from is the one with that repo's name holding that slug — first
    holder only when no repo is named, first feed only when nothing holds it —
    and strip pills are keyed by repo and slug, so two same-slug builds keep
    two pills. Driven through the twin over two repos sharing a slug."""
    pick = ctx["shown_feed"]

    def feed(name, *slugs):
        return {"name": name, "state": {"binders": [{"slug": s} for s in slugs]}}
    a, b, c = feed("alpha", "same", "a-only"), feed("beta", "same"), feed("gamma")
    feeds = [a, b, c]
    if pick(feeds, "same", "beta") is not b or pick(feeds, "same", "alpha") is not a:
        return False
    if pick(feeds, "same", None) is not a or pick(feeds, "a-only", "beta") is not a:
        return False
    if pick(feeds, "none", None) is not a or pick([], "x", None) is not None:
        return False
    page, app, py = ctx["page"], ctx["app_src"], ctx["py_twins"]
    rows = _tags_with(page, "data-kw-home-build")
    pills = _tags_with(page, "data-kw-strip-pill")
    if len(rows) != 1 or len(pills) != 1:
        return False
    if (_attrs(rows[0]).get("@click") != "go('open', b.slug, b.repo)"
            or _attrs(pills[0]).get("@click") != "go('open', p.slug, p.repo)"
            or _attrs(pills[0]).get(":key") != "p.repo + '/' + p.slug"):
        return False
    go = _js_block(app, "    go(action, slug, repo) {")
    shown = _js_block(app, "    shownFeed() {")
    fn = _js_block(app, "function shownFeedOf(feeds, slug, repo) {")
    pills_js = _js_block(app, "function stripPillsOf(feeds) {")
    return ("if (action === 'open') this.binderRepo = (repo === undefined) ? null : repo;" in go
            and "binderRepo: null," in _js_block(app, "  data() {")
            and "shownFeedOf(this.feeds, this.shownSlug," in shown and "this.binderRepo" in shown
            and "repo !== null && f.name === repo && holds(f)" in fn
            and "|| all.find(holds) || all[0] || null" in fn
            and "Object.assign({ repo: f.name || '' }, p)" in pills_js
            and "strip() { return stripPillsOf(this.feeds); }," in app
            and "MIRROR: change together with shown_feed()" in app
            and "MIRROR: change together with shownFeedOf()" in py.get("shown_feed", ""))


@_covers("hub-landing-is-gone", kind="behaviour",
         breaks=[lambda c: {"hub": _with_hook_inserted(c["hub"], "data-kw-main", "a", "data-kw-hub-card")},
                 lambda c: {"module_names": c["module_names"] + ["render_hub_html"]},
                 lambda c: {"hub_dispatch": c["hub_dispatch"] + "\n# render_hub_html(cards)"}])
def _c_hub_landing_gone(ctx):
    """The old landing is gone, not left beside the page that replaced it: no
    document carries its card, slug, verdict or empty hooks, and none of its
    renderer, its stylesheet, its reload script or its chip and treatment
    tables exist any more."""
    hooks = ("data-kw-hub-card", "data-kw-hub-slug", "data-kw-hub-verdict", "data-kw-hub-empty",
             "data-kw-hub-egg", "data-kw-hub-wordmark")
    for key in _DOC_KEYS:
        if any(_tags_with(ctx[key], h) for h in hooks):
            return False
    gone = ("render_hub_html", "_HUB_CSS", "_HUB_JS", "_HUB_CHIP", "_HUB_TREATMENT")
    return (not set(gone) & set(ctx["module_names"])
            and "render_hub_html" not in ctx["hub_dispatch"]
            and "location.reload(" not in ctx["hub"])


@_covers("hub-no-meta-refresh", kind="behaviour",
         breaks=[lambda c: {"hub": c["hub"].replace(
             "<head>", '<head><meta http-equiv="refresh" content="10">')},
                 lambda c: {"hub_empty": c["hub_empty"].replace(
                     "<head>", '<head><meta http-equiv="refresh" content="30">')}])
def _c_hub_no_meta_refresh(ctx):
    """The ten-second meta refresh is replaced, not supplemented. No rendered
    document declares a refresh through http-equiv — a mechanism that cannot
    read the reader's choice and cannot be stopped by it has no second life
    beside the one that can."""
    for key in _DOC_KEYS:
        for tag in _tags_named(ctx[key], "meta"):
            if "refresh" in _attrs(tag).get("http-equiv", "").lower():
                return False
    return True


